def _auto_install(package: str, pip_spec: str = "") -> None:
    """Install a missing Python package automatically via pip."""
    spec = pip_spec or package
    subprocess.check_call(
        [sys.executable, "-m", "pip", "install", "-q", spec],
        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
    )
    # Force re-import after install
    importlib.invalidate_caches()


# ---------------------------------------------------------------------------
# Shared event type
# ---------------------------------------------------------------------------

class StreamEvent:
    """A single event from a streaming model response."""

    __slots__ = ("type", "text", "input_tokens", "output_tokens", "stop_reason",
                 "cost_usd", "tool_name", "tool_input", "tool_output",
                 "cached_tokens", "output_truncated", "output_chars",
                 "output_notes", "seen_text")

    def __init__(
        self,
        type: str,
        text: str = "",
        input_tokens: int = 0,
        output_tokens: int = 0,
        stop_reason: str | None = None,
        cost_usd: float = 0.0,
        tool_name: str = "",
        tool_input: str = "",
        tool_output: str = "",
        cached_tokens: int = 0,
        output_truncated: bool = False,
        output_chars: int = 0,
        output_notes: str = "",
        seen_text: str = "",
    ):
        self.type = type
        self.text = text
        self.input_tokens = input_tokens
        self.output_tokens = output_tokens
        self.stop_reason = stop_reason
        self.cost_usd = cost_usd
        self.tool_name = tool_name
        self.tool_input = tool_input
        self.tool_output = tool_output
        # Prompt tokens served from the endpoint's prefix cache (OpenAI/vLLM
        # ``prompt_tokens_details.cached_tokens`` or Anthropic
        # ``cache_read_input_tokens``). 0 when unreported. Lets us SEE caching.
        self.cached_tokens = cached_tokens
        # ``tool_output`` is a 2000-char HEAD slice for display. Anything a
        # consumer needs to know about the REST of the result has to travel
        # as its own field, or it cannot be recovered downstream:
        #
        # * ``output_truncated`` — the model did not see the whole result.
        #   The engine's count guard used to sniff the "… truncated, N chars
        #   …" marker out of ``tool_output``, but that marker is written to
        #   the CONTEXT copy, after this event is built, and bash puts its
        #   own marker ~4000 chars in — past the slice either way. So the
        #   guard armed on small results and stayed silent on exactly the
        #   large ones it exists for.
        # * ``output_chars`` — full length of the result before slicing.
        # * ``output_notes`` — the reader's own NOTE lines. read_document
        #   appends them AFTER the grid, and a 200-row grid is ~10 kB, so
        #   the note saying a column cannot be read never reached the guard
        #   that consumes it.
        self.output_truncated = output_truncated
        self.output_chars = output_chars
        self.output_notes = output_notes
        # * ``seen_text`` — the result as the model was given it (after the
        #   context cut, before the data fence). The evidence pool is filled
        #   from it: filled from the preview, a figure past character 2000
        #   of a result the model saw whole was flagged as unsupported.
        #   Empty where a backend passes the result through whole, and
        #   never written to a trace.
        self.seen_text = seen_text


# ---------------------------------------------------------------------------
# Backend base
# ---------------------------------------------------------------------------

class _BaseClient:
    """Common interface for both backends."""

    #: True only for a backend that mints the session id itself and
    #: announces it on the stream. The engine leaves ``session_id`` empty
    #: for those and fills it in from the event; for everyone else an
    #: empty id is not "not known yet", it is a bucket every session in
    #: the workspace shares — which is how one session's task list ends up
    #: reported as another's. Declared here so the question is answered by
    #: the object that was actually built, not by the backend string that
    #: was asked for: ``create_client`` returns an OpenAIClient for
    #: provider kit/ollama/openai whatever ``backend`` says.
    supplies_session_id: bool = False

    def preset_session_id(self, session_id: str) -> bool:
        """Take ``session_id`` as the id of the conversation not begun yet.

        For a backend that announces its id: one that can be told the id
        up front answers True, and the session has its id before the
        first turn -- the service's log and presence are keyed by it from
        the start. False (the default): the id stays "" until the stream
        announces it.
        """
        return False

    def stream_message(
        self,
        system: str,
        messages: list[dict[str, Any]],
        max_tokens: int = 8192,
        session_id: str = "",
        thinking_budget: int = 0,
        no_tools: bool = False,
    ) -> Generator[StreamEvent, None, None]:
        raise NotImplementedError

    def narrow_tool_surface(
        self, allowed: Any = (), denied: Any = ()
    ) -> None:
        """Restrict THIS session to *allowed* minus *denied*, where possible.

        Default: do nothing. A backend that cannot enforce a tool list must
        not pretend to — the caller compares what it asked for against
        ``enforced_tool_surface`` and tells the user about the difference,
        which is the only version of that check that cannot go stale.
        """
        return None

    def enforced_tool_surface(self) -> tuple[tuple[str, ...], tuple[str, ...]]:
        """``(allow, deny)`` this client will really enforce. Empty = none."""
        return ((), ())

    def signal_stop(self) -> None:
        """Cooperative stop: nudge a running turn to end without tearing down
        the underlying connection or session. Default is no-op; backends that
        own a long-lived subprocess should override to send SIGINT so the
        next turn can ``--resume`` the same conversation. The engine's
        ``request_stop`` flag handles the Python-side stream cutoff.
        """
        return None


# ---------------------------------------------------------------------------
# CLI backend (uses OAuth -- no API key needed)
# ---------------------------------------------------------------------------

# Credentials each CLI backend needs for itself; every other secret is
# removed from its environment.
_CLAUDE_CLI_KEYS = ("ANTHROPIC_API_KEY", "ANTHROPIC_AUTH_TOKEN",
                    "CLAUDE_CODE_OAUTH_TOKEN")
_CODEX_CLI_KEYS = ("OPENAI_API_KEY", "CODEX_API_KEY")


def _cli_backend_env(own_keys: tuple[str, ...]) -> dict:
    """The environment for an external agent CLI: the shell's scrubbed
    environment plus the credentials that CLI itself runs on."""
    env = _scrubbed_bash_env()
    for key in own_keys:
        if os.environ.get(key):
            env[key] = os.environ[key]
    return env


# Secret files in the Claude CLI's permission-rule syntax (gitignore-style
# patterns; ``~/`` is the home directory). Kept to the kinds of secret the
# native deny list names, not its name globs such as "credentials*", which
# would also hide source files.
_CLI_SECRET_PATTERNS: tuple[str, ...] = (
    "**/.env", "**/.env.*", "**/*.env", "**/.envrc",
    "**/*.key", "**/*.pem", "**/*.p12", "**/*.pfx", "**/*.secret",
    "**/.ssh/**", "~/.ssh/**", "**/.gnupg/**", "~/.gnupg/**",
    "**/.netrc", "~/.netrc", "**/.git-credentials", "~/.git-credentials",
    "**/.aws/credentials", "~/.aws/credentials", "**/.npmrc", "**/.pypirc",
    "**/.pgpass", "~/.kube/**", "~/.docker/config.json",
    "~/.delfin/credentials.json", "~/.delfin/trust_store/**",
    "**/id_rsa", "**/id_dsa", "**/id_ecdsa", "**/id_ed25519",
)


def _cli_secret_deny_rules() -> list[str]:
    return [f"{verb}({pattern})" for verb in ("Read", "Edit")
            for pattern in _CLI_SECRET_PATTERNS]


class CLIClient(_BaseClient):
    """Persistent bidirectional CLI-backend client via ``--input-format stream-json``.

    Spawns a single long-running ``claude -p`` process that accepts JSON
    messages on stdin and emits JSON events on stdout — identical to what
    the terminal CLI does internally.  The process stays alive across
    multiple turns, giving the same context management, caching, and
    permission handling as the interactive terminal.

    Parameters
    ----------
    model : str
        Model alias (``"sonnet"``, ``"opus"``, ``"haiku"``).
    claude_path : str
        Path to the ``claude`` binary.  Auto-detected if empty.
    permission_mode : str
        CLI permission mode (``"default"``, ``"acceptEdits"``, etc.).
    """

    # The level is a subprocess flag, fixed when the process starts.
    EFFORT_PER_REQUEST = False

    DEFAULT_MODEL = "sonnet"
    supplies_session_id = True          # emits a session_init event

    def __init__(self, model: str = "", claude_path: str = "",
                 permission_mode: str = "", cwd: str = "",
                 mcp_config: str = "",
                 allowed_tools: list[str] | None = None,
                 extra_dirs: list[str] | None = None,
                 effort: str = "",
                 read_only_dirs: list[str] | None = None,
                 confirm_callback: Optional[Callable[[str, dict, str], bool]] = None):
        self.model = model or self.DEFAULT_MODEL
        self.permission_mode = permission_mode
        self.cwd = cwd or None
        self.mcp_config = mcp_config  # path to MCP config JSON or empty
        self.allowed_tools = allowed_tools  # restrict CLI to these tools only
        self.extra_dirs = extra_dirs  # extra writable directories (--add-dir)
        # Effort level for reasoning/thinking (low/medium/high/xhigh/max).
        # Empty = use the CLI's default. Passed via `--effort <level>`.
        self.effort = (effort or "").strip().lower()
        self.claude_path = claude_path or shutil.which("claude") or "claude"
        if not shutil.which(self.claude_path):
            raise FileNotFoundError(
                f"Agent CLI binary not found at '{self.claude_path}'. "
                "Install it from https://claude.ai/code"
            )
        self._proc: subprocess.Popen | None = None
        self._session_id: str = ""
        #: The id a new conversation is started under (``--session-id``)
        #: until the CLI has announced it; from then on it is resumed.
        self._new_session_id: str = ""
        # DELFIN's file gate in front of the CLI's own tools (cli_gate):
        # the same read/write boundary, and the same dialog, as every
        # other backend. One token per client; the relay carries the
        # hook's questions to ``confirm_callback``.
        self.read_only_dirs = list(read_only_dirs or ())
        self.confirm_callback = confirm_callback
        from . import cli_gate as _cli_gate
        self._gate_token = _cli_gate.new_token()
        self._gate_relay = None

    def set_confirm_callback(self, callback) -> None:
        """Who the gate asks. Applies to the next tool call."""
        self.confirm_callback = callback
        self._write_gate_state()
        self._start_gate_relay()

    def _write_gate_state(self) -> None:
        from . import cli_gate as _cli_gate
        _cli_gate.write_state(
            self._gate_token,
            workspace=str(Path(self.cwd or os.getcwd()).resolve()),
            mode=self.permission_mode or "default",
            can_ask=self.confirm_callback is not None,
            extra_dirs=list(self.extra_dirs or ()),
            read_only_dirs=self.read_only_dirs)

    def _start_gate_relay(self) -> None:
        from . import cli_gate as _cli_gate
        if self._gate_relay is not None:
            self._gate_relay.stop()
            self._gate_relay = None
        if self.confirm_callback is not None:
            self._gate_relay = _cli_gate.Relay(
                self._gate_token, self.confirm_callback).start()

    def enforced_tool_surface(self) -> tuple[tuple[str, ...], tuple[str, ...]]:
        """The allow list handed to the subprocess; no deny list exists here.

        The tool loop runs inside the child process, so the only lever is the
        command line built in ``_ensure_proc``. Reporting the empty deny list
        honestly is what lets the caller warn instead of silently dropping it.
        """
        return (tuple(self.allowed_tools or ()), ())

    def _ensure_proc(self, system: str, session_id: str = "") -> subprocess.Popen:
        """Start the persistent CLI process if not already running."""
        if self._proc is not None and self._proc.poll() is None:
            return self._proc

        cmd = [
            self.claude_path,
            "-p",
            "--input-format", "stream-json",
            "--output-format", "stream-json",
            "--verbose",
            "--include-partial-messages",
            "--include-hook-events",
            "--model", self.model,
            "--append-system-prompt", system,
        ]

        if self.permission_mode and self.permission_mode != "default":
            if self.permission_mode == "bypassPermissions":
                cmd.append("--dangerously-skip-permissions")
            else:
                # "auto" is a mode of the CLI's own, with its own checks.
                # It was passed as --dangerously-skip-permissions, which
                # turns every check off -- the user chose the mode that
                # asks less, not the one that asks nothing.
                cmd.extend(["--permission-mode", self.permission_mode])

        # DELFIN's secret deny list, in the CLI's rule syntax, and DELFIN's
        # own file gate as a PreToolUse hook (cli_gate): the CLI runs its
        # own tools, so without it they never met the boundary every other
        # backend keeps -- under Bypass, reads and writes anywhere. Deny
        # rules and a hook's deny both hold in every CLI mode, bypass
        # included. No gate state, no start: an unchecked CLI is not the
        # fallback.
        from . import cli_gate as _cli_gate
        self._write_gate_state()
        self._start_gate_relay()
        cmd.extend(["--settings", json.dumps(
            {"permissions": {"deny": _cli_secret_deny_rules()},
             "hooks": _cli_gate.hook_settings(self._gate_token)})])

        if self.mcp_config:
            cmd.extend(["--mcp-config", self.mcp_config])

        if self.allowed_tools is not None:
            cmd.extend(["--allowedTools", ",".join(self.allowed_tools)])

        if self.extra_dirs:
            for d in self.extra_dirs:
                cmd.extend(["--add-dir", d])

        if self.effort in ("low", "medium", "high", "xhigh", "max"):
            cmd.extend(["--effort", self.effort])

        if session_id and session_id == self._new_session_id:
            # Nothing to resume yet: the conversation begins under this id.
            cmd.extend(["--session-id", session_id])
        elif session_id:
            cmd.extend(["--resume", session_id])

        self._proc = subprocess.Popen(
            cmd,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            cwd=self.cwd,
            # Every key but the CLI's own: its shell tool inherits this,
            # and `env` would put the KIT or OpenAI key into a transcript
            # that goes to another provider.
            env=_cli_backend_env(_CLAUDE_CLI_KEYS),
            # Its own process group, so a Ctrl+C in a terminal front-end
            # does not reach it. This process is deliberately long-lived
            # across turns, and signal_stop() sends it a SIGINT on purpose
            # — one that preserves the session so the next turn can
            # --resume. A second SIGINT arriving straight from the tty
            # would race that controlled stop and tear down the
            # conversation instead of pausing it. kill() still applies.
            start_new_session=True,
        )
        return self._proc

    def stream_message(
        self,
        system: str,
        messages: list[dict[str, Any]],
        max_tokens: int = 8192,
        session_id: str = "",
        thinking_budget: int = 0,
        no_tools: bool = False,
    ) -> Generator[StreamEvent, None, None]:
        """Send a message and stream the response via the persistent process.

        The first call spawns the CLI process.  Subsequent calls re-use it,
        giving the same conversation continuity as the terminal CLI.
        """
        # Extract last user message
        prompt_text = ""
        for msg in reversed(messages):
            if msg["role"] == "user":
                prompt_text = msg["content"]
                break

        # Empty user content would cause the CLI to forward a content block
        # tagged with cache_control on empty text → Anthropic API rejects
        # with "cache_control cannot be set for empty text blocks". Skip the
        # send instead — caller can resume the existing session next turn.
        _text = prompt_text if isinstance(prompt_text, str) else ""
        if not _text.strip():
            return

        # Use existing session_id if we have one from a prior turn
        effective_sid = session_id or self._session_id

        proc = self._ensure_proc(system, session_id=effective_sid)

        # Build the stream-json input message
        user_msg = json.dumps({
            "type": "user",
            "message": {
                "role": "user",
                "content": [{"type": "text", "text": prompt_text}],
            },
        }, ensure_ascii=False)

        try:
            proc.stdin.write(user_msg + "\n")
            proc.stdin.flush()
        except (BrokenPipeError, OSError):
            # Process died — restart it
            self._proc = None
            proc = self._ensure_proc(system, session_id=effective_sid)
            proc.stdin.write(user_msg + "\n")
            proc.stdin.flush()

        # Read events until we get the "result" event (turn complete)
        yield from self._read_turn(proc)

    def _read_turn(self, proc: subprocess.Popen) -> Generator[StreamEvent, None, None]:
        """Read events from stdout until a ``result`` event marks turn end."""
        emitted_text = False
        current_tool_name = ""
        current_tool_input_chunks: list[str] = []
        in_thinking_block = False
        in_tool_result_block = False
        tool_result_chunks: list[str] = []
        # Map tool_use IDs to names so we can label tool_result events
        _tool_id_to_name: dict[str, str] = {}
        _last_tool_use_id = ""

        for line in proc.stdout:
            line = line.strip()
            if not line:
                continue
            try:
                data = json.loads(line)
            except json.JSONDecodeError:
                continue

            dtype = data.get("type", "")

            if dtype == "system" and data.get("subtype") == "init":
                sid = data.get("session_id", "")
                if sid:
                    self._session_id = sid
                    self._new_session_id = ""
                    yield StreamEvent(type="session_init", text=sid)

            elif dtype == "stream_event":
                evt = data.get("event", {})
                etype = evt.get("type", "")

                if etype == "content_block_start":
                    block = evt.get("content_block", {})
                    btype = block.get("type", "")
                    if btype == "tool_use":
                        current_tool_name = block.get("name", "")
                        current_tool_input_chunks = []
                        # Track tool_use ID for matching with tool_result
                        tid = block.get("id", "")
                        if tid and current_tool_name:
                            _tool_id_to_name[tid] = current_tool_name
                            _last_tool_use_id = tid
                    elif btype == "thinking":
                        in_thinking_block = True
                    elif btype == "tool_result":
                        in_tool_result_block = True
                        tool_result_chunks = []

                elif etype == "content_block_delta":
                    delta = evt.get("delta", {})
                    dtyp = delta.get("type", "")
                    if dtyp == "text_delta":
                        text = delta.get("text", "")
                        if text:
                            if in_tool_result_block:
                                tool_result_chunks.append(text)
                            else:
                                emitted_text = True
                                yield StreamEvent(type="text_delta", text=text)
                    elif dtyp == "thinking_delta":
                        text = delta.get("thinking", "")
                        if text:
                            yield StreamEvent(type="thinking_delta", text=text)
                    elif dtyp == "input_json_delta":
                        current_tool_input_chunks.append(
                            delta.get("partial_json", "")
                        )

                elif etype == "content_block_stop":
                    if in_thinking_block:
                        in_thinking_block = False
                    elif in_tool_result_block:
                        in_tool_result_block = False
                        result_text = "".join(tool_result_chunks)
                        if result_text:
                            # Match to last tool_use name if possible
                            result_tool = _tool_id_to_name.get(
                                _last_tool_use_id, ""
                            )
                            # Redacted where the EVENT is built, not where
                            # the model copy is made: the engine writes this
                            # event to the tool trace, and a bug report
                            # bundles that file and adds group-read to it.
                            # Redacting only on the way into the context
                            # protected the model and left the disk open.
                            yield StreamEvent(
                                type="tool_result",
                                tool_name=result_tool,
                                tool_output=_redact_tool_result(result_text),
                            )
                        tool_result_chunks = []
                    elif current_tool_name:
                        tool_input = "".join(current_tool_input_chunks)
                        yield StreamEvent(
                            type="tool_use",
                            tool_name=current_tool_name,
                            tool_input=tool_input,
                        )
                        current_tool_name = ""
                        current_tool_input_chunks = []

                elif etype == "message_start":
                    usage = (evt.get("message") or {}).get("usage", {})
                    inp = (
                        usage.get("input_tokens", 0)
                        + usage.get("cache_creation_input_tokens", 0)
                        + usage.get("cache_read_input_tokens", 0)
                    )
                    if inp:
                        yield StreamEvent(
                            type="message_start", input_tokens=inp
                        )

            elif dtype == "assistant":
                msg = data.get("message", {})
                for block in msg.get("content", []):
                    btype = block.get("type", "")
                    if btype == "tool_use":
                        tool_name = block.get("name", "")
                        tool_input = json.dumps(
                            block.get("input", {}), ensure_ascii=False
                        )
                        # Track ID
                        tid = block.get("id", "")
                        if tid and tool_name:
                            _tool_id_to_name[tid] = tool_name
                            _last_tool_use_id = tid
                        if not current_tool_name:
                            yield StreamEvent(
                                type="tool_use",
                                tool_name=tool_name,
                                tool_input=tool_input,
                            )

            elif dtype == "user":
                # User messages contain tool_result blocks (CLI internal)
                msg = data.get("message", {})
                for block in msg.get("content", []):
                    if block.get("type") == "tool_result":
                        content = block.get("content", "")
                        # content can be string or list of content blocks
                        if isinstance(content, list):
                            parts = []
                            for cb in content:
                                if isinstance(cb, dict) and cb.get("type") == "text":
                                    parts.append(cb.get("text", ""))
                            content = "\n".join(parts)
                        if content:
                            tid = block.get("tool_use_id", "")
                            result_tool = _tool_id_to_name.get(tid, "")
                            yield StreamEvent(
                                type="tool_result",
                                tool_name=result_tool,
                                tool_output=_redact_tool_result(str(content)),
                            )

            elif dtype == "result":
                usage = data.get("usage", {})
                total_input = (
                    usage.get("input_tokens", 0)
                    + usage.get("cache_creation_input_tokens", 0)
                    + usage.get("cache_read_input_tokens", 0)
                )
                total_output = usage.get("output_tokens", 0)
                total_cost = data.get("total_cost_usd", 0.0)
                sid = data.get("session_id", "")
                if sid:
                    self._session_id = sid

                for denial in data.get("permission_denials", []):
                    yield StreamEvent(
                        type="permission_denied",
                        tool_name=str(denial),
                    )

                if not emitted_text:
                    result_text = data.get("result", "")
                    if result_text:
                        yield StreamEvent(type="text_delta", text=result_text)

                yield StreamEvent(
                    type="message_delta",
                    input_tokens=total_input,
                    output_tokens=total_output,
                    cost_usd=total_cost,
                    stop_reason=data.get("stop_reason", "end_turn"),
                    text=sid,
                )
                # Turn complete — stop reading, wait for next send
                return

        # Falling off the loop means stdout ended without a ``result``
        # event, so this turn produced no message_delta. Returning quietly
        # here -- which three of the four exits below used to do -- hands
        # the engine a turn with no text and no error, and an answerless
        # turn takes the user's question with it: the message stays in the
        # history unanswered, and the next send is merged over it by the
        # alternation sanitiser. This generator therefore ends in exactly
        # two ways: a message_delta, or a raise the caller can show.
        rc = proc.poll()
        if rc is not None:
            # Always clear dead process reference so _ensure_proc() restarts
            self._proc = None
            if rc != 0:
                stderr = proc.stderr.read() if proc.stderr else ""
                if "Not logged in" in stderr:
                    raise RuntimeError(
                        "Agent CLI is not logged in. "
                        "Run 'claude' in a terminal and complete login first."
                    )
                if stderr.strip():
                    raise RuntimeError(
                        f"CLI backend error (exit {rc}): {stderr.strip()[:500]}"
                    )
                # Non-zero and NOT one word of stderr. That is what a
                # process killed from outside looks like -- SIGKILL from
                # the OOM killer reports rc == -9 and says nothing at all.
                if rc < 0:
                    raise RuntimeError(
                        f"CLI backend was killed by signal {-rc} before it "
                        f"finished the turn (no error output; signal 9 is "
                        f"typically the out-of-memory killer). The turn was "
                        f"not answered and nothing was added to the history."
                    )
                raise RuntimeError(
                    f"CLI backend exited with code {rc} before finishing the "
                    f"turn and wrote no error output. The turn was not "
                    f"answered and nothing was added to the history."
                )
            # Exit code 0, no result event: a clean exit mid-turn is still
            # an unanswered turn, and reporting it as success is what let
            # the question be overwritten.
            raise RuntimeError(
                "CLI backend exited cleanly without completing the turn "
                "(no result event). The turn was not answered and nothing "
                "was added to the history."
            )
        # Still alive, but its stdout is closed or exhausted -- nothing
        # more will ever arrive on this pipe, so the turn cannot complete.
        # Retiring the process (rather than just dropping the reference)
        # keeps the next send from inheriting the same dead pipe, and
        # leaves no orphan behind. The session id survives, so the
        # replacement resumes the same conversation.
        try:
            self.kill()
        except Exception:
            self._proc = None
        raise RuntimeError(
            "CLI backend stopped streaming without ending the turn (the "
            "process is still running but its output stream ended). The "
            "turn was not answered and nothing was added to the history."
        )

    def switch_model(self, model: str) -> None:
        """Switch the model by killing the current process.

        The next ``stream_message`` call will spawn a new process with
        the updated model.  The session ID is preserved so conversation
        context is maintained via ``--resume``.
        """
        if model and model != self.model:
            self.kill()
            self.model = model

    def kill(self) -> None:
        """Kill the persistent CLI process."""
        if self._proc is not None:
            try:
                self._proc.terminate()
                self._proc.wait(timeout=5)
            except Exception:
                try:
                    self._proc.kill()
                except Exception:
                    pass
            self._proc = None

    def signal_stop(self) -> None:
        """Soft-stop: SIGINT the CLI subprocess so the current turn ends
        cooperatively. The session_id is preserved so the next send can
        resume via ``--resume``. If SIGINT fails or the process is gone,
        we fall back to a regular kill (still safe — resume handles it).
        """
        proc = self._proc
        if proc is None or proc.poll() is not None:
            return
        try:
            proc.send_signal(signal.SIGINT)
        except Exception:
            try:
                proc.terminate()
            except Exception:
                pass
            self._proc = None

    def preset_session_id(self, session_id: str) -> bool:
        """A new conversation is started with ``--session-id``. Not while
        one is live (a running process, an announced id): that one goes on
        under the id it has."""
        if self._session_id or (self._proc is not None and self._proc.poll() is None):
            return False
        self._new_session_id = session_id
        return True

    @property
    def session_id(self) -> str:
        """Return the current CLI session ID."""
        return self._session_id


# ---------------------------------------------------------------------------
# API backend (uses Anthropic API key)
# ---------------------------------------------------------------------------

class APIClient(_BaseClient):
    """Use the Anthropic Python SDK directly.

    Requires an API key (``ANTHROPIC_API_KEY`` or passed explicitly).
    Supports text streaming, extended thinking, tool_use events,
    cost tracking, and model switching.
    """

    # The thinking budget is derived per turn from the session's level.
    EFFORT_PER_REQUEST = True

    DEFAULT_MODEL = "claude-sonnet-4-20250514"

    # Pricing lives in delfin.agent.pricing -- one table for the whole
    # repo, and no fallback rate. The table that used to sit here was
    # keyed by dated ids while the dropdown hands this client "opus" /
    # "sonnet" / "haiku", so not one of its three keys was reachable and
    # every call silently took the (3.0, 15.0) fallback.

    def __init__(self, api_key: str = "", model: str = ""):
        try:
            import anthropic  # noqa: F401
        except ImportError:
            _auto_install("anthropic", "anthropic>=0.40")
            import anthropic  # noqa: F401
        from .credentials import load_credential as _load_cred_anth
        resolved_key = api_key or _load_cred_anth("ANTHROPIC_API_KEY")
        if not resolved_key:
            raise ValueError(
                "No Anthropic API key found. Either set ANTHROPIC_API_KEY in "
                "the environment, or run `delfin-agent "
                "credentials set ANTHROPIC_API_KEY` to store it in "
                "~/.delfin/credentials.json (chmod 0600)."
            )
        import anthropic

        self.model = self._checked_model(model or self.DEFAULT_MODEL)
        self.client = anthropic.Anthropic(api_key=resolved_key)

    @staticmethod
    def _checked_model(model: str) -> str:
        """Refuse a tier alias here rather than let the vendor refuse it.

        The provider dropdown's fallback list ships ``opus`` / ``sonnet``
        / ``haiku``. They are valid for the CLI backend, which resolves
        them itself; this client puts the string straight into the
        request body, so on the API backend every such run died on a
        vendor 404 -- after the session, the engine and the tool schemas
        had all been built. One sentence at the point where the contract
        is known beats an opaque failure on the first turn.

        Resolving the alias to a dated id instead would be a guess about
        WHICH model the caller gets -- the same guess ``pricing`` refuses
        to make about the rate behind these three names.
        """
        from delfin.agent import pricing
        mid = (model or "").strip()
        if mid in pricing.DECLARED_UNPRICED:
            # Name the pinned ids of that same tier — the alias is
            # ambiguous precisely because several of them exist.
            same_tier = sorted(k for k in pricing.ANTHROPIC_RATES
                               if mid in k)
            usable = ", ".join(same_tier or sorted(pricing.ANTHROPIC_RATES))
            raise ValueError(
                f"'{mid}' is a tier alias, not a model id the Messages API "
                f"accepts — the API backend needs a pinned id (e.g. "
                f"{usable}). Aliases work on the CLI backend, which "
                f"resolves them itself."
            )
        return mid

    def switch_model(self, model: str) -> None:
        """Switch model (no process to kill, just update the name)."""
        if model and model != self.model:
            self.model = self._checked_model(model)

    def kill(self) -> None:
        """No-op — API client has no persistent process."""

    @property
    def session_id(self) -> str:
        """API backend has no session concept."""
        return ""

    def _estimate_cost(self, input_tokens: int, output_tokens: int) -> float:
        """USD for this turn, or 0.0 when no USD spend can be measured.

        There is no fallback rate any more. When ``pricing`` has no entry
        for the model, this turn contributes nothing to the running total
        instead of contributing an invented number -- and consumers ask
        ``pricing.resolve`` whether that zero is a measured zero or an
        absent measurement before showing it as money.
        """
        return pricing.cost_usd(self.model, "claude",
                                input_tokens, output_tokens) or 0.0

    def stream_message(
        self,
        system: str,
        messages: list[dict[str, Any]],
        max_tokens: int = 8192,
        session_id: str = "",
        thinking_budget: int = 0,
        no_tools: bool = False,
    ) -> Generator[StreamEvent, None, None]:
        """Stream via the Anthropic Messages API.

        Handles text, thinking, tool_use, and cost events.
        """
        # Explicit prompt-cache breakpoint on the system prompt: the prompt
        # loader keeps it byte-stable across turns precisely so the provider
        # can serve it from cache — without the marker none of that
        # engineering pays off on this backend. cache_read_input_tokens is
        # already folded into the metrics above/below.
        _system_param: Any = system
        if system:
            _system_param = [{
                "type": "text",
                "text": system,
                "cache_control": {"type": "ephemeral"},
            }]
        kwargs: dict[str, Any] = {
            "model": self.model,
            "max_tokens": max_tokens,
            "system": _system_param,
            "messages": messages,
        }
        if thinking_budget > 0:
            kwargs["thinking"] = {
                "type": "enabled",
                "budget_tokens": thinking_budget,
            }

        _in_thinking = False
        _in_tool_use = False
        _tool_name = ""
        _tool_input_chunks: list[str] = []
        _total_in = 0
        _total_out = 0

        with self.client.messages.stream(**kwargs) as stream:
            for event in stream:
                etype = getattr(event, "type", "")

                if etype == "message_start":
                    usage = getattr(
                        getattr(event, "message", None), "usage", None
                    )
                    if usage:
                        _total_in = getattr(usage, "input_tokens", 0)
                        cache_creation = getattr(usage, "cache_creation_input_tokens", 0)
                        cache_read = getattr(usage, "cache_read_input_tokens", 0)
                        _total_in += cache_creation + cache_read
                        yield StreamEvent(
                            type="message_start",
                            input_tokens=_total_in,
                            cached_tokens=cache_read,
                        )

                elif etype == "content_block_start":
                    block = getattr(event, "content_block", None)
                    block_type = getattr(block, "type", "") if block else ""
                    if block_type == "thinking":
                        _in_thinking = True
                    elif block_type == "tool_use":
                        _in_tool_use = True
                        _tool_name = getattr(block, "name", "")
                        _tool_input_chunks.clear()

                elif etype == "content_block_delta":
                    delta = getattr(event, "delta", None)
                    if not delta:
                        continue
                    delta_type = getattr(delta, "type", "")
                    if delta_type == "text_delta":
                        yield StreamEvent(
                            type="text_delta",
                            text=getattr(delta, "text", ""),
                        )
                    elif delta_type == "thinking_delta":
                        yield StreamEvent(
                            type="thinking_delta",
                            text=getattr(delta, "thinking", ""),
                        )
                    elif delta_type == "input_json_delta":
                        _tool_input_chunks.append(
                            getattr(delta, "partial_json", "")
                        )

                elif etype == "content_block_stop":
                    if _in_thinking:
                        _in_thinking = False
                    if _in_tool_use:
                        _in_tool_use = False
                        tool_input = "".join(_tool_input_chunks)
                        yield StreamEvent(
                            type="tool_use",
                            tool_name=_tool_name,
                            tool_input=tool_input,
                        )
                        _tool_name = ""
                        _tool_input_chunks.clear()

                elif etype == "message_delta":
                    usage = getattr(event, "usage", None)
                    out_tokens = (
                        getattr(usage, "output_tokens", 0) if usage else 0
                    )
                    _total_out = out_tokens
                    cost = self._estimate_cost(_total_in, _total_out)
                    yield StreamEvent(
                        type="message_delta",
                        output_tokens=out_tokens,
                        stop_reason=(
                            getattr(event.delta, "stop_reason", None)
                            if hasattr(event, "delta")
                            else None
                        ),
                        cost_usd=cost,
                    )


# ---------------------------------------------------------------------------
# OpenAI backend (uses OpenAI API key)
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# KIT-Toolbox coding-agent permissions (.delfin-style safety layer)
# ---------------------------------------------------------------------------

# Bash patterns that are ALWAYS rejected (case-insensitive substring/regex
# match against the raw command string). Keep this list tight: false positives
# block the user, but missing entries can cause real damage.
# Ephemeral sinks a shell command may always write to: scratch space and
# device sinks hold no user data, so gating them would only produce noise.
_BASH_SCRATCH_PREFIXES: tuple[str, ...] = ("/tmp/", "/var/tmp/", "/dev/")
_BASH_SCRATCH_EXACT: frozenset[str] = frozenset({"/tmp", "/var/tmp"})

# Commands whose destination is the LAST positional argument.
_BASH_DEST_LAST: frozenset[str] = frozenset({
    "cp", "mv", "rsync", "install", "unzip", "git-clone",
})
# Commands where EVERY positional argument is a write target.
_BASH_DEST_ALL: frozenset[str] = frozenset({
    "mkdir", "touch", "rm", "rmdir", "tee", "truncate", "shred",
})
# Options that carry a write destination as their value.
_BASH_DEST_OPTS: frozenset[str] = frozenset({
    "-o", "--output", "--output-file", "-C", "--directory", "-d",
    "--target", "--prefix", "--root", "--output-dir", "--dest",
})

# Short options that mean something OTHER than a destination, per command.
#
# `-d` is a destination for `unzip` and `install`, a DELIMITER for `cut`,
# a date string for `date`, and a PREDICATE for `test`. Read as a
# destination it made `test -d /etc && echo yes` a write to /etc -- a
# refusal to check whether a directory exists -- and `cut -d , -f1
# data.csv` a write to ",". Same failure as reading `s.replace(',', '.')`
# as Path.replace: one name, two meanings, told apart by context.
#
# Per (command, option) rather than per command, because the distinction
# is per option: `sort -d` is dictionary order and `sort -o` really does
# write its output file. Long options are unambiguous and are never
# suppressed. An empty set means "every short dest-option", for commands
# that cannot write at all.
_BASH_NO_DEST_OPTS: dict[str, frozenset[str]] = {
    "test": frozenset(), "[": frozenset(),
    "grep": frozenset(), "egrep": frozenset(), "fgrep": frozenset(),
    "rg": frozenset(), "ag": frozenset(),
    "cmp": frozenset(), "comm": frozenset(), "diff": frozenset(),
    "sdiff": frozenset(), "ls": frozenset(), "find": frozenset(),
    "wc": frozenset(), "head": frozenset(), "tail": frozenset(),
    "cut": frozenset(), "uniq": frozenset(), "join": frozenset(),
    "paste": frozenset(), "column": frozenset(), "date": frozenset(),
    "od": frozenset(), "xxd": frozenset(),
    # Shell builtins whose -o names an OPTION: `set -o pipefail` is the
    # prefix the test recipe puts in front of every gate run.
    "set": frozenset(), "shopt": frozenset(),
    # ...and the one that writes, where only the ambiguous flag is muted.
    "sort": frozenset({"-d"}),
}


# `git -C <repo>` says WHICH repository to work in. Whether that is a write
# is decided by the SUBCOMMAND, not by -C: `git -C /elsewhere commit` writes
# there, `git -C /elsewhere log` reads. Read as a destination for every
# subcommand, a plain read of another checkout was refused as a write to it
# — measured 2026-09-18, a session running `git -C <repo> log --oneline -3`
# was told the path "is in a READ-ONLY location", which is true and beside
# the point, and lost the call.
#
# Fail closed: only these mute the option, and every one of them is
# read-only with no flag that changes that. `branch`, `tag`, `remote`,
# `config`, `stash` and `worktree` are deliberately absent — each has a
# spelling that writes.
_GIT_READ_ONLY_SUBCOMMANDS: frozenset[str] = frozenset({
    "log", "show", "status", "diff", "diff-tree", "diff-index", "blame",
    "shortlog", "describe", "reflog", "for-each-ref", "rev-parse",
    "rev-list", "ls-files", "ls-tree", "cat-file", "grep", "whatchanged",
    "merge-base", "show-ref", "name-rev", "count-objects", "check-ignore",
    "version",
})

#: git's own options that carry a value, so the subcommand is not mistaken
#: for one of their arguments.
_GIT_GLOBAL_OPTS_WITH_VALUE: frozenset[str] = frozenset({
    "-C", "-c", "--git-dir", "--work-tree", "--namespace", "--exec-path",
})


def _git_subcommand(rest: list[str]) -> str:
    """The subcommand in a git argument list, or "" when there is none."""
    i = 0
    while i < len(rest):
        arg = rest[i]
        if not arg.startswith("-"):
            return arg
        if "=" not in arg and arg in _GIT_GLOBAL_OPTS_WITH_VALUE:
            i += 2          # the option, and the value it carries
        else:
            i += 1
    return ""


#: Subcommands that read only in some spellings. Fail closed: anything not
#: matching the listed read form counts as a write.
_GIT_LIST_FLAGS_BRANCH = frozenset({
    "--show-current", "--list", "-l", "-a", "--all", "-r", "--remotes",
    "-v", "-vv", "--verbose", "--no-color", "--no-column",
})


def _git_reads_only(rest: list[str]) -> bool:
    sub = _git_subcommand(rest)
    after = rest[rest.index(sub) + 1:] if sub in rest else []
    if sub == "reflog":
        # `reflog expire` / `reflog delete` rewrite the reflog.
        return not any(a in ("expire", "delete") for a in after)
    if sub == "branch":
        # Only the listing form reads; a name or -d/-m/-c/-u writes.
        return bool(after) and all(a in _GIT_LIST_FLAGS_BRANCH for a in after)
    if sub == "symbolic-ref":
        # Reading: options plus at most the ref name; a second positional
        # sets the ref.
        positional = [a for a in after if not a.startswith("-")]
        return len(positional) <= 1 and all(
            a in ("--short", "-q", "--quiet") for a in after if a.startswith("-"))
    return sub in _GIT_READ_ONLY_SUBCOMMANDS


def _dest_opt_applies(name: str, opt: str) -> bool:
    """Whether *opt* names a destination for command *name*."""
    if opt.startswith("--"):
        return True
    muted = _BASH_NO_DEST_OPTS.get(name)
    if muted is None:
        return True
    return bool(muted) and opt not in muted


# Commands whose whole purpose is to emit a file's contents. Reading is not
# gated in general — half of a shell session legitimately touches paths
# outside the workspace (interpreters, system tools, /proc) — but these are
# the direct substitute for a refused read_file.
# Commands that print the CONTENTS of a file named on their command line.
#
# The gate this feeds exists because "a refusal that one tool honours and
# the next ignores is not a refusal" -- and the set was written narrowly
# enough that four other spellings of `cat` walked straight past it.
# Measured against main on 2026-09-09, with the workspace elsewhere:
#
#     cat /etc/passwd                 blocked
#     grep root /etc/passwd           printed it
#     awk '{print}' /etc/passwd       printed it
#     sed -n 1,2p /etc/passwd         printed it
#     cut -d: -f1 /etc/passwd         printed it
#
# All four are on the auto-allow list, so an agent that had a read_file
# refused could reach the same bytes with the next line it typed.
#
# Only ABSOLUTE and `~` arguments are inspected (see _bash_outside_reads),
# so ordinary work is untouched: `grep -rn foo .`, `sed -n 1,50p src/x.py`
# and every relative path stay exactly as they were.
#
# Metadata-only commands are deliberately NOT here -- wc, file, stat,
# md5sum and sha256sum report a size, a type or a digest, and gating a
# question about a file's existence would be friction with nothing behind
# it.
_BASH_CONTENT_READERS: frozenset[str] = frozenset({
    "cat", "head", "tail", "less", "more", "strings", "xxd", "od",
    "base64", "nl", "tac", "bat",
    "grep", "egrep", "fgrep", "rg", "ag", "ack",
    "awk", "gawk", "mawk", "sed", "cut", "sort", "uniq", "paste",
    "column", "fold", "expand", "unexpand", "rev", "jq", "yq",
    "zcat", "zgrep", "bzcat", "xzcat",
    # `diff /etc/passwd /etc/hosts` prints all of both, and diff is on the
    # auto-allow list. A fifth spelling of cat, found in the same sweep.
    # `cmp` reports an offset by default but `cmp -b` prints the bytes.
    "diff", "cmp", "comm", "sdiff",
})


#: A path-shaped word in a command line: absolute, or home-relative.
_PATH_WORD_RE = re.compile(
    r"(?<![A-Za-z0-9_.~$-])(?:~|\$\{HOME\}|\$HOME|/)[^\s;|&<>()`'\"]*")


def _path_words(cmd: str) -> list[str]:
    """The absolute paths a command line names, normalised."""
    home = str(Path.home())
    out = []
    for raw in _PATH_WORD_RE.findall(cmd or ""):
        word = (raw.replace("${HOME}", home).replace("$HOME", home))
        if word.startswith("~"):
            word = os.path.expanduser(word)
        if word.startswith("/"):
            word = "/" + word.lstrip("/")
            out.append(os.path.normpath(word))
    return out


def _path_covers(path: str, words: list[str]) -> bool:
    """Whether any word names *path* or something inside it."""
    inside = path.rstrip("/") + "/"
    for word in words:
        if word == path or (path != "/" and word.startswith(inside)):
            return True
        if any(c in word for c in "*?[") and fnmatch.fnmatch(path, word):
            return True
    return False


def _deep_enough(path: str) -> bool:
    """Two or more components: specific enough to match as a substring."""
    return len([part for part in path.split("/") if part]) >= 2


def _bash_reads_denied_path(cmd: str, denied: set,
                            roots: "list | tuple" = ()) -> str:
    """Reason string when a shell command would fetch a path the user has
    already refused this session, else "".

    A refusal covers the DATA, not the tool that asked, so a refused file is
    also refused through its directory -- independent of the command used.

    It used to be matched as a plain substring of the command line. A
    refused '/' (an agent asked to read the filesystem root and was told
    no) then blocked every later command with a slash in it, the session's
    own test runner included; a refused '/tests' blocked every path
    containing '/tests'; and a refused file directly in the home directory
    extended to the home directory itself, which holds the workspace.
    Measured in a supervised run: one correct refusal left a session unable
    to run anything. Now: a short path (the root, one component) matches
    only as a whole path word, or a path inside it -- the root only as
    itself; a deeper path still matches as a substring, bounded at its end,
    so it is also caught glued to an option (``-a/data/secret/x``); and the
    directory around a refused file is refused with it only when that
    directory could have been opened by an approved read in the first
    place -- never the home, a system or a key directory.

    A refused directory that CONTAINS the session's workspace (or another
    of its roots) is refused as itself only. Refusing to list the home
    directory blocked every later command naming a path under it -- the
    workspace, the session's own test gate -- and the session could run
    nothing (supervised night run, 2026-09-25). Reading the workspace is
    what the session was granted; the refusal was about the directory.
    """
    try:
        if not denied or not cmd:
            return ""
        # A segment's PROGRAM is run, not read: a refused read of the
        # session's own test gate blocked every later run of that gate
        # (night run 2026-09-25). Only what follows the program is
        # scanned -- `cat <refused>` and `bash <refused>` stay refused,
        # because there the file is an argument that gets read.
        cmd = " ; ".join(
            seg.split(None, 1)[1] if len(seg.split(None, 1)) > 1 else ""
            for seg in _split_shell_segments(cmd))
        words = _path_words(cmd)
        norm_roots = [os.path.normpath(str(r)) for r in roots or () if r]
        for path in denied:
            p = os.path.normpath(str(path)) if path else ""
            if not p:
                continue
            if any(r == p or r.startswith(p.rstrip("/") + "/")
                   for r in norm_roots):
                # The refused directory holds a granted root: only a
                # command that names the directory itself is refused.
                if any(w.rstrip("/") == p.rstrip("/") for w in words):
                    return f"the user refused '{p}' earlier in this session"
                continue
            if _path_covers(p, words) or (
                    _deep_enough(p) and re.search(
                        re.escape(p) + r"(?![A-Za-z0-9_.\-])", cmd)):
                return f"the user refused '{p}' earlier in this session"
            # Refusing a file also refuses reaching it through its directory.
            parent = os.path.dirname(p)
            if (_deep_enough(parent) and _is_grantable_read_dir(parent)
                    and (_path_covers(parent, words) or re.search(
                        re.escape(parent) + r"(?![A-Za-z0-9_.\-])", cmd))):
                return (f"the user refused '{p}', and this command reaches "
                        f"its directory '{parent}'")
    except Exception:
        return ""
    return ""
    return ""


# Commands that print what a DIRECTORY holds: its names, and with `find`
# or `tree` everything below it. Not content readers, but a listing of a
# folder outside the workspace is still a look outside it -- `ls /home/x`
# and `find ~ -name '*.log'` reached past a read_file the user would have
# been asked about. Absolute and `~` arguments only, like the readers.
_BASH_DIR_LISTERS: frozenset[str] = frozenset({"ls", "find", "tree"})

# `cd X && cat file` reads X/file by a relative name, which the reader
# check above never sees. The directory changed into is the thing to ask
# about. A bare `cd` goes home.
_BASH_DIR_CHANGERS: frozenset[str] = frozenset({"cd", "pushd", "popd"})

#: Where a `cd` leads when the gate cannot know: into a variable, a
#: command substitution, `cd -` with no earlier cd in the command (the
#: shell's $OLDPWD), `popd` on a stack this command did not build. No
#: root contains it, so a path reported under it is refused or asked.
_UNRESOLVED_DIR = Path(
    "/<directory this command changed into could not be resolved>")

#: Words that may stand before a command without being it (`if cd x;`,
#: `then (cd y && …)`, `! cd z`).
_SHELL_LEAD_WORDS: frozenset[str] = frozenset({
    "if", "then", "elif", "else", "while", "until", "do", "!", "{", "time",
})

#: Programs whose own option moves the directory for that one command.
_CHDIR_OPTIONS: dict[str, tuple[str, ...]] = {
    "git": ("-C",),
    "make": ("-C", "--directory"),
    "gmake": ("-C", "--directory"),
    "env": ("-C", "--chdir"),
}


#: `$NAME` or `${NAME}`; every other `$` form is not resolved.
_SHELL_VAR_REF = re.compile(
    r"\$(?:\{([A-Za-z_][A-Za-z0-9_]*)\}|([A-Za-z_][A-Za-z0-9_]*))")

#: Every name: the command can set any variable (`source`, `eval`, `.`).
_ALL_NAMES = frozenset({"*"})


def _shell_names_set_opaquely(cmd: str) -> "frozenset | set":
    """Variable names whose value at a `cd` the gate cannot read off the
    command: set by anything other than a standalone `NAME=literal`
    (`for NAME in`, `read NAME`, `declare NAME=`, `printf -v NAME`,
    `NAME=$(…)`, `W=x prog` …), or written inside single quotes, where
    `$NAME` is not expanded at all. ``_ALL_NAMES`` when the command runs
    `source`, `.` or `eval`, which can set any of them.

    Errs one way only: a name listed here is unresolved, and an
    unresolved cd is asked about or refused. Never raises.
    """
    import shlex
    try:
        text = cmd or ""
        ok: dict = {}
        for seg in _split_shell_segments(text):
            try:
                words = shlex.split(seg)
            except ValueError:
                return _ALL_NAMES
            while words and words[0] in _SHELL_LEAD_WORDS:
                words = words[1:]
            if words:
                words[0] = words[0].lstrip("(")
            if words and Path(words[0]).name in ("source", ".", "eval"):
                return _ALL_NAMES
            if words and words[0] == "export":
                words = words[1:]
            if words and all(re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", w)
                             for w in words):
                for w in words:
                    name, value = w.split("=", 1)
                    if "$(" in value or "`" in value:
                        continue
                    ok[name] = ok.get(name, 0) + 1
        out: set = set()
        for m in _SHELL_VAR_REF.finditer(text):
            name = m.group(1) or m.group(2)
            if name in out:
                continue
            bare = [b for b in re.finditer(
                rf"(?<![\w${{]){re.escape(name)}(?!\w)(?!=)", text)]
            assigned = len(re.findall(
                rf"(?<![\w$]){re.escape(name)}=", text))
            quoted = any(f"${name}" in q or f"${{{name}}}" in q
                         for q in re.findall(r"'[^']*'", text))
            if bare or quoted or assigned > ok.get(name, 0):
                out.add(name)
        return out
    except Exception:
        return _ALL_NAMES


class _ShellDirWalk:
    """The directory a shell command is in, followed command by command.

    Input: ``start`` -- where the command begins, or None for "the
    caller's base" (a relative name then stays relative, which is what the
    write scanner hands on to a gate that resolves against its own cwd).
    ``oldpwd`` is where a `cd -` goes before any cd in this command:
    unresolved by default, because that is the shell's $OLDPWD.

    Per simple command, ``enter(segment, argv)`` returns ``(argv, moved)``:
    the words with subshell parentheses removed, and True when the
    command was `cd`/`pushd`/`popd` and has been followed. ``here`` is the
    directory the command runs in; ``command_dir(argv)`` adds a `-C` of
    git/make/env for that one command. ``leave()`` after the command
    closes the subshells it ended, so ``(cd x) && y`` runs y where the
    command began. ``visited`` lists every directory reached.

    Followed: `cd X`, `cd` (home), `cd ~/X`, `cd $HOME/X`, `cd -`,
    `pushd X`, `pushd` (swap), `popd`, `( … )`, `$( … )` (a cd inside a
    substitution does not move the outer shell), and `if`/`then`/`!`/`{`
    before a cd. `$NAME`/`${NAME}` in a target resolves from ``env`` (the
    environment the command will run with) and from standalone literal
    assignments earlier in the command (`W=sub; cd $W`), unless the
    command may set NAME some other way (_shell_names_set_opaquely).
    Unresolved: any other `$` form, an unset or opaquely set name, a
    backquote, `cd -` with no earlier cd, `popd` on an empty stack,
    `pushd +N`. CDPATH is not read (a relative cd is taken as relative to
    the current directory).

    One instance per pass over a command; the read scanner, the write
    scanner and the script content scan each drive their own, so the three
    agree on where a relative name lands. Rejected: three hand-kept
    copies of this state machine, which is how `(cd /x && echo > f)` came
    to be followed by none of them and `popd` by one.
    """

    def __init__(self, start: "Path | None", oldpwd: "Path | None" = None,
                 env: "dict | None" = None, cmd: str = ""):
        self.here = start
        self.previous = _UNRESOLVED_DIR if oldpwd is None else oldpwd
        self.stack: list = []
        self.frames: list = []       # ("sub", saved state) | ("cmd"|"plain", None)
        self.pending: "tuple | None" = None
        self.visited: list = [start]
        # Variables a cd target may name: the environment the command runs
        # with (_scrubbed_bash_env) and the literal assignments seen so far
        # (None = assigned something unknowable). Names the command may set
        # any other way are never resolved (_shell_names_set_opaquely).
        self.env = dict(env or {})
        self.vars: dict = {}
        self.tainted = _shell_names_set_opaquely(cmd) if env is not None else None

    @property
    def unresolved(self) -> bool:
        return self.here == _UNRESOLVED_DIR

    def _state(self) -> tuple:
        return (self.here, self.previous, list(self.stack), dict(self.vars))

    def _expand(self, text: str) -> "str | None":
        """*text* with `$NAME` / `${NAME}` replaced, or None when any part
        cannot be known: a substitution, another `$` form, a name the
        command sets other than by a literal assignment, an unset name."""
        if "`" in text or "$(" in text:
            return None
        if "$" not in text:
            return text
        if self.tainted is None:
            return None
        if "$" in _SHELL_VAR_REF.sub("", text):
            return None              # ${X:-y}, $1, $?, ...
        unknown = False

        def _value(m: "re.Match") -> str:
            nonlocal unknown
            name = m.group(1) or m.group(2)
            if self.tainted is _ALL_NAMES or name in self.tainted:
                unknown = True
                return ""
            value = (self.vars[name] if name in self.vars
                     else self.env.get(name))
            if value is None:
                unknown = True
                return ""
            return value

        out = _SHELL_VAR_REF.sub(_value, text)
        return None if unknown else out

    def _assign(self, words: list) -> None:
        """Record `NAME=literal` (also after `export`) as the shell will."""
        if words and words[0] == "export":
            words = words[1:]
        for w in words:
            m = re.match(r"^([A-Za-z_][A-Za-z0-9_]*)=(.*)$", w, re.S)
            if m:
                self.vars[m.group(1)] = self._expand(m.group(2))

    def _target(self, dest: str) -> "Path | None":
        dest = _home_expanded(dest)
        if "$" in dest:
            dest = self._expand(dest)
            if dest is None:
                return _UNRESOLVED_DIR
        if "`" in dest:
            return _UNRESOLVED_DIR
        dest = os.path.expanduser(dest)
        if dest.startswith("/"):
            return Path(dest)
        if self.here == _UNRESOLVED_DIR:
            return _UNRESOLVED_DIR
        return Path(dest) if self.here is None else self.here / dest

    def _go(self, target: "Path | None") -> None:
        self.previous, self.here = self.here, target
        self.visited.append(target)

    def _follow(self, words: list) -> None:
        name = Path(words[0]).name
        args = [a for a in words[1:] if a == "-" or not a.startswith("-")]
        if name == "popd":
            self._go(self.stack.pop() if self.stack else _UNRESOLVED_DIR)
            return
        if name == "pushd":
            if not args:
                if self.stack:
                    top = self.stack.pop()
                    self.stack.append(self.here)
                    self._go(top)
                return
            if args[0][:1] in "+" or (args[0][:1] == "-" and args[0] != "-"):
                self._go(_UNRESOLVED_DIR)
                return
            self.stack.append(self.here)
        if args and args[0] == "-":
            self._go(self.previous)
            return
        self._go(self._target(args[0]) if args else
                 Path(os.path.expanduser("~")))

    def enter(self, segment: str, argv: list) -> tuple:
        words = list(argv)
        depth: list = []             # open substitutions before each word
        # A here-document body is the program's input, not shell: its
        # parentheses are code. Only the command line before it counts.
        if re.search(r"<<(?!<)", segment):
            segment = segment.split("\n", 1)[0]
        if "(" in segment or ")" in segment:
            try:
                import shlex as _shlex
                lx = _shlex.shlex(segment, posix=True, punctuation_chars="()")
                lx.whitespace_split = True
                toks = list(lx)
            except ValueError:
                toks = None
            if toks is not None:
                # The re-split words replace the caller's only when a
                # subshell or substitution opens or closes here; a `(` in
                # code (`print(x)`, a here-document line) leaves them as
                # they were.
                structural = False
                words = []
                for tok in toks:
                    if tok and set(tok) <= {"(", ")"}:
                        for ch in tok:
                            if ch == "(":
                                if words and words[-1].endswith("$"):
                                    words[-1] = words[-1][:-1]
                                    if not words[-1]:
                                        words.pop()
                                        depth.pop()
                                    self.frames.append(("cmd", None))
                                    structural = True
                                elif all(w in _SHELL_LEAD_WORDS for w in words):
                                    self.frames.append(("sub", self._state()))
                                    structural = True
                                else:
                                    self.frames.append(("plain", None))
                            elif self.frames:
                                kind, saved = self.frames.pop()
                                if kind == "sub":
                                    self.pending = saved
                                structural = structural or kind != "plain"
                        continue
                    words.append(tok)
                    depth.append(sum(1 for k, _ in self.frames if k == "cmd"))
                if not structural:
                    words = list(argv)
                    depth = []
        if not depth:
            inside = sum(1 for k, _ in self.frames if k == "cmd")
            depth = [inside] * len(words)
        lead = 0
        while lead < len(words) and words[lead] in _SHELL_LEAD_WORDS:
            lead += 1
        i = lead
        while i < len(words) and re.match(
                r"^[A-Za-z_][A-Za-z0-9_]*=", words[i]):
            i += 1
        if (i < len(words) and depth[i] == 0
                and Path(words[i]).name in _BASH_DIR_CHANGERS):
            self._follow(words[i:])
            return words, True
        # `W=sub` or `export W=sub` on its own sets a shell variable; one
        # in front of a program (`W=sub prog`) sets it for that program only.
        rest = words[lead:]
        if rest and rest[0] == "export":
            rest = rest[1:]
        if (rest and not any(depth[lead:]) and all(
                re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", w) for w in rest)):
            self._assign(words[lead:])
        return words, False

    def leave(self) -> None:
        if self.pending is not None:
            self.here, self.previous, self.stack, self.vars = self.pending
            self.pending = None

    def command_dir(self, argv: list) -> "Path | None":
        """Where this one command runs: ``here``, moved by its own `-C`."""
        words = [w for w in argv
                 if not re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", w)]
        if not words:
            return self.here
        opts = _CHDIR_OPTIONS.get(Path(words[0]).name)
        if not opts:
            return self.here
        prog = Path(words[0]).name
        where = self.here
        rest = words[1:]
        k = 0
        while k < len(rest):
            w = rest[k]
            dest = None
            for opt in opts:
                if w == opt and k + 1 < len(rest):
                    dest = rest[k + 1]
                    k += 1
                elif w.startswith(opt + "=") and opt.startswith("--"):
                    dest = w[len(opt) + 1:]
                elif opt == "-C" and w.startswith("-C") and len(w) > 2:
                    dest = w[2:]
            k += 1
            if dest is None:
                if w in ("-c", "-u", "-f", "--file", "-I", "-o", "-W", "-S"):
                    k += 1          # the option's own value
                elif not w.startswith("-") and prog != "make" and prog != "gmake":
                    break           # git's subcommand, env's program
                continue
            saved = self.here
            self.here = where
            where = self._target(dest)
            self.here = saved
        if where != self.here:
            self.visited.append(where)
        return where


def _bash_visited_dirs(cmd: str, base: "str | Path") -> list:
    """Every known directory a command runs a command in, ``base`` first.

    For checks that look at the names in a command without pairing each
    name with its command (the secret-link test, the locked scope's
    symlink test): a relative name is tried in each of these, which can
    only find more. Unresolvable directories are left out; the content
    scan and the write scanner, which pair names with commands, handle
    those. Never raises.
    """
    import shlex
    start = Path(base)
    walk = _ShellDirWalk(start, oldpwd=start, env=_scrubbed_bash_env(), cmd=cmd or "")
    try:
        for seg in _split_shell_segments(cmd or ""):
            walk.leave()
            try:
                toks = shlex.split(seg)
            except ValueError:
                toks = seg.split()
            toks, moved = walk.enter(seg, toks)
            if not moved:
                walk.command_dir(toks)
    except Exception:
        pass
    out: list = []
    for d in walk.visited:
        if d is None or d == _UNRESOLVED_DIR:
            continue
        d = d if d.is_absolute() else start / d
        if d not in out:
            out.append(d)
    return out or [start]


def _is_system_path(word: str) -> bool:
    """True for interpreter, binary and library directories (no user data)."""
    text = os.path.normpath(os.path.expanduser(word))
    return (text in _SYSTEM_DIRS
            or (text + "/").startswith(_SYSTEM_PATH_PREFIXES))


#: Programs that touch no file named on their command line: they print
#: their arguments, look up names, or report metadata only. Every OTHER
#: program's path arguments are reads -- `python x.py /data/run.out`,
#: `cp /data/a .`, `git -C /other/repo log` all look outside as surely as
#: `cat` does. wc, stat, file and the digests are here on purpose: a size
#: or a hash is not the content, and asking about it is friction with
#: nothing behind it.
_BASH_NO_FILE_PROGRAMS: frozenset[str] = frozenset({
    "echo", "printf", "true", "false", "exit", "export", "unset", "set",
    "which", "type", "command", "hash", "alias", "sleep", "kill", "date",
    "wc", "stat", "file", "md5sum", "sha1sum", "sha256sum", "sha512sum",
    "test", "[", "[[", "basename", "dirname", "realpath", "readlink",
    "mkdir", "touch", "rm", "rmdir", "chmod", "squeue", "scancel", "sacct",
})

#: Read-only system information. Not user data, and asked for by every
#: core-count check a calculation script does.
_SYSTEM_INFO_FILES: frozenset[str] = frozenset({
    "/proc/cpuinfo", "/proc/meminfo", "/proc/loadavg", "/proc/version",
    "/proc/uptime", "/etc/os-release", "/etc/hostname",
})


#: Programs that hand the REST of their words to another program to run.
#: The first non-option, non-`NAME=value` word is the REAL command word,
#: and its path must not be scanned as a read -- executing a program is
#: not reading it. Each value lists the option spellings that take a
#: SEPARATE value (skipped together with that value while the wrapper's
#: options are walked); a flag or a self-contained `-n5`/`--x=5` needs no
#: entry. `timeout` is the one with two leading positionals (DURATION
#: then COMMAND); every other wrapper's first bare word is its program.
#:
#: The wrappers' own operands that ARE files (``env -C /dir``) are not
#: touched here: only the command-word index is skipped, so the wrapper's
#: file-like operands and every following argument are still scanned.
_COMMAND_WORD_WRAPPERS: dict[str, frozenset[str]] = {
    "env": frozenset({"-u", "--unset", "-C", "--chdir", "-S", "-P",
                      "--default-signal", "--block-signal", "--list-signal"}),
    "timeout": frozenset({"-k", "--kill-after", "-s", "--signal"}),
    "nice": frozenset({"-n", "--adjustment"}),
    "ionice": frozenset({"-c", "--class", "-n", "--classdata",
                         "-p", "--pid"}),
    "taskset": frozenset({"-c", "--cpu-list"}),
    "nohup": frozenset(),
    "setsid": frozenset(),
    "command": frozenset(),
}


def _home_expanded(word: str) -> str:
    home = str(Path.home())
    for spelling in ("${HOME}", "$HOME"):
        if word.startswith(spelling):
            return home + word[len(spelling):]
    return word


def _glob_root(word: str) -> str:
    """The directory a glob reads: everything before its first wildcard
    component. `/data/run*/x.out` reads /data."""
    parts = word.split("/")
    keep = []
    for part in parts:
        if any(c in part for c in "*?["):
            break
        keep.append(part)
    root = "/".join(keep)
    return root or ("/" if word.startswith("/") else ".")


def _read_exempt(path: str) -> bool:
    """System directories, pseudo-devices, system info.

    NOT /tmp: on a shared login node it holds other users' files, and
    read_file asks there -- a shell exemption made `cat /tmp/x` the way
    around that question (caught by CI, where test folders live in /tmp).
    Writing scratch to /tmp stays free; reading it back asks once, and the
    approval opens the directory for the session."""
    text = os.path.normpath(path)
    return (_is_system_path(text) or _is_safe_device(text)
            or text in _SYSTEM_INFO_FILES
            or text.startswith("/proc/self/"))


def _shell_segments(cmd: str) -> list[str]:
    """``cmd`` split at ``;``, ``&``, ``|`` and newlines OUTSIDE quotes.

    Splitting inside quotes cut `sh -c "a; b"` into pieces with a stray
    quote each, and the stray quote then became part of a "path"."""
    out: list[str] = []
    cur: list[str] = []
    quote = ""
    i = 0
    text = cmd or ""
    while i < len(text):
        ch = text[i]
        if quote:
            if ch == "\\" and quote == '"' and i + 1 < len(text):
                cur.append(ch + text[i + 1])
                i += 2
                continue
            if ch == quote:
                quote = ""
            cur.append(ch)
        elif ch in "'\"":
            quote = ch
            cur.append(ch)
        elif ch == "\\" and i + 1 < len(text):
            cur.append(ch + text[i + 1])
            i += 2
            continue
        elif ch == "&" and ((i > 0 and text[i - 1] in "<>")
                            or (i + 1 < len(text) and text[i + 1] == ">")):
            cur.append(ch)          # 2>&1, &>file: a redirection, not a split
        elif ch in ";&|\n":
            out.append("".join(cur))
            cur = []
        else:
            cur.append(ch)
        i += 1
    out.append("".join(cur))
    return [seg for seg in out if seg.strip()]


_SHELL_PROGRAMS: frozenset[str] = frozenset({"sh", "bash", "zsh", "dash", "ksh"})


# awk, whose first operand is its own program, not a file,
# with the options that take a separate value and the ones that supply the
# script instead (then no operand is the script). Measured 2026-10-19: the
# awk program `/<script>$/,/^<\/script>$/ {print}` was asked about four
# times as a read of an absolute path outside the workspace. grep and sed
# are not here: _pattern_blanked already blanks their pattern and script
# before this scanner runs, so their first operand left is a FILE -- adding
# them skipped `/etc/passwd` in `grep root /etc/passwd`.
_SCRIPT_FIRST_PROGRAMS: dict[str, tuple[frozenset, frozenset]] = {
    p: (frozenset({"-F", "-v", "-f", "-i", "-l", "-E", "--field-separator",
                   "--assign", "--file", "--include", "--load", "--exec"}),
        frozenset({"-f", "--file", "-E", "--exec"}))
    for p in ("awk", "gawk", "mawk", "nawk")
}


def _script_argument_index(prog: str, args: list) -> Optional[int]:
    """Index in *args* of the operand *prog* reads as its script or
    pattern (awk's program, sed's script, grep's pattern), or None."""
    spec = _SCRIPT_FIRST_PROGRAMS.get(prog)
    if spec is None:
        return None
    takes_value, supplies_script = spec
    skip = False
    for i, a in enumerate(args):
        if skip:
            skip = False
            continue
        if a == "--":
            return i + 1 if i + 1 < len(args) else None
        if a.startswith("-") and a != "-":
            opt = a.split("=", 1)[0]
            if opt in supplies_script or (
                    not opt.startswith("--") and len(opt) > 2
                    and opt[:2] in supplies_script):
                return None
            if opt in takes_value and "=" not in a:
                skip = True
            continue
        return i
    return None


def _executed_command_index(prog: str, args: list) -> Optional[int]:
    """Index in *args* of the program the wrapper `prog` delegates to.

    A delegating wrapper (``env``, ``timeout``, ``nice``, …) hands the
    rest of its words to another program to run. That inner program is
    a simple command's command word: its PATH must not be scanned as a
    read -- executing a program is not reading it (2026-10-29: a venv
    interpreter run under ``env X=1`` was asked about as an
    outside-workspace read). Returns the index of that word so the caller
    can skip exactly it, leaving every sibling argument -- the wrapper's
    own operands and the program's following arguments -- scanned as
    before. ``--`` ends the wrapper's options. ``timeout`` has a leading
    DURATION positional before its COMMAND, so its program is the second
    bare word; every other wrapper's first bare word is the program.
    Returns None when `prog` is not a delegation wrapper, or when no bare
    word occupies the command-word slot (a wrapper with only options or
    only a duration leaves nothing to skip).
    """
    value_opts = _COMMAND_WORD_WRAPPERS.get(prog)
    if value_opts is None:
        return None
    # How many bare words precede the program: timeout's DURATION, and
    # taskset's MASK unless -c/--cpu-list gave the CPU list as an option
    # value. taskset -p works on an existing pid and runs no program.
    leading = 1 if prog == "timeout" else 0
    if prog == "taskset":
        if any(a in ("-p", "--pid") or (a.startswith("-") and not a.startswith("--")
                                        and "p" in a[1:]) for a in args):
            return None
        if not any(a in ("-c", "--cpu-list") or a.startswith("--cpu-list=")
                   for a in args):
            leading = 1
    positional = 0
    skip = False
    options_done = False
    for i, a in enumerate(args):
        if skip:
            skip = False
            continue
        if not options_done and a == "--":
            options_done = True     # every later word is positional
            continue
        if not options_done and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", a):
            continue               # env's NAME=value, not the program
        if options_done or not a.startswith("-"):
            if positional == leading:
                return i
            positional += 1
            continue               # the DURATION or MASK, not yet the program
        opt = a.split("=", 1)[0]
        if opt in value_opts and "=" not in a:
            skip = True            # the option takes a separate value
        # a value-less flag, or a self-contained -n5 / --x=5: nothing to skip
    return None


def _bash_outside_reads(cmd: str, cwd: "str | Path | None" = None,
                        _depth: int = 0) -> list[str]:
    """Paths a shell command would read, for the outside-read gate.

    Every path argument of every program counts, except programs that
    touch no file (``_BASH_NO_FILE_PROGRAMS``) and exempt locations
    (``_read_exempt``). Also counted: ``cd``/``pushd`` targets (a bare cd
    is home), input redirections (``< file``), option values
    (``--input=/x``), the directory a glob reads, and paths inside an
    inline python payload.

    Absolute and home paths (``~``, ``$HOME``) are returned as written.
    With ``cwd`` -- where the command starts -- relative paths are
    returned too, resolved against the directory the command is in at
    that point: ``cd sub && cat ../../x`` is followed through the cd, and
    the gate resolves symlinks, so a link that points out is caught where
    it points. Without ``cwd`` relative paths are not inspected.

    History: only the absolute arguments of a list of content readers
    were inspected, so `cd /etc && cat hostname`, `ls ~`, `cp /x .`,
    `cat ../../x` and `cat $HOME/.bashrc` all read outside the workspace
    without a question in every mode (2026-10-09).
    """
    out: list[str] = []
    try:
        srcs = list(_inline_payload.extract_c_payloads(cmd) or [])
        srcs += _inline_payload.extract_stdin_payloads(
            cmd, include_expanded=True)
        for src in srcs:
            for tok in _inline_payload.analyze_payload(src).reads:
                tok = _home_expanded(tok)
                if tok.startswith("/") or tok.startswith("~"):
                    out.append(tok)
                elif cwd is not None and ".." in Path(tok).parts:
                    out.append(str(Path(cwd) / tok))
    except Exception:
        pass
    here: "Path | None" = Path(cwd) if cwd is not None else None
    # `cd -` before any cd stays where the command began, as it always did
    # here; an unknown directory stops the resolving of relative names.
    walk = _ShellDirWalk(here, oldpwd=here, env=_scrubbed_bash_env(), cmd=cmd)

    def _known(where: "Path | None") -> "Path | None":
        if where is None or where == _UNRESOLVED_DIR or not where.is_absolute():
            return None
        return where

    def _add(word: str) -> None:
        word = _home_expanded(word)
        if not word or word.startswith("$") or word.startswith("<"):
            return
        if any(c in word for c in "*?["):
            word = _glob_root(word)
        if word.startswith("/") or word.startswith("~"):
            if not _read_exempt(os.path.expanduser(word)):
                out.append(word)
            return
        if here is not None:
            full = str(here / word)
            if not _read_exempt(full):
                out.append(full)

    def _segment_reads(argv: list, moved: bool) -> None:
        if moved:
            # The directory changed into is itself looked at.
            words = [w for w in argv if w not in _SHELL_LEAD_WORDS
                     and not re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", w)]
            name = Path(words[0]).name
            rest = [a for a in words[1:] if a == "-" or not a.startswith("-")]
            if name == "popd" or (rest and rest[0] == "-") or (
                    name == "pushd" and not rest):
                return
            dest = _home_expanded(rest[0]) if rest else "~"
            target = walk.here
            if target is None or target == _UNRESOLVED_DIR:
                return
            if dest.startswith("/") or dest.startswith("~"):
                if not _read_exempt(os.path.expanduser(dest)):
                    out.append(dest)
            elif target.is_absolute() and not _read_exempt(str(target)):
                out.append(str(target))
            return
        while argv and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", argv[0]):
            argv = argv[1:]
        if not argv:
            return
        prog = Path(argv[0]).name
        args = argv[1:]
        # `sh -c "…"` runs a whole command line: judge that line too,
        # from where this one is at that point.
        if prog in _SHELL_PROGRAMS and "-c" in args and _depth < 3:
            i = args.index("-c")
            if i + 1 < len(args):
                out.extend(_bash_outside_reads(
                    args[i + 1], here, _depth + 1))
            return
        # `env -S "STRING"` (--split-string) splits STRING into a new command
        # line, like `sh -c`: judge that line, with the words after it.
        if prog == "env" and _depth < 3:
            for i, a in enumerate(args):
                split = None
                if a in ("-S", "--split-string") and i + 1 < len(args):
                    split, tail = args[i + 1], args[i + 2:]
                elif a.startswith("--split-string="):
                    split, tail = a.split("=", 1)[1], args[i + 1:]
                elif a.startswith("-S") and len(a) > 2:
                    split, tail = a[2:], args[i + 1:]
                if split is not None:
                    line = " ".join([split] + [shlex.quote(t) for t in tail])
                    out.extend(_bash_outside_reads(line, here, _depth + 1))
                    return
        # Input redirection reads, whatever the program.
        for i, a in enumerate(args):
            if a == "<" and i + 1 < len(args):
                _add(args[i + 1])
            elif a.startswith("<") and not a.startswith("<<") and len(a) > 1:
                _add(a[1:])
        if prog in _BASH_NO_FILE_PROGRAMS:
            return
        script_at = _script_argument_index(prog, args)
        # A delegating wrapper's program word (env X=1 prog, timeout 20
        # prog, nice prog) is the command word of a simple command: its
        # path is not a read, whatever position the shell resolved it to.
        cmd_at = _executed_command_index(prog, args)
        skip_next = False
        for i, a in enumerate(args):
            if skip_next:
                skip_next = False
                continue
            if i == script_at or i == cmd_at:
                continue    # the program's script/pattern or command word, not a file
            if a in ("<", ">", ">>", "2>", "2>>", "&>", "&>>", ">|"):
                skip_next = True    # the redirection's own target
                continue
            if (a.startswith("<") or a.startswith(">")
                    or (a[:1] in "0123456789&" and ">" in a[:3])):
                continue
            if a.startswith("-"):
                if "=" in a:
                    _add(a.split("=", 1)[1])
                continue
            if prog == "dd" and a.startswith("if="):
                _add(a[3:])
                continue
            if "=" in a.split("/")[0]:
                continue
            looks_like_path = ("/" in a or a.startswith("~")
                               or a.startswith("$HOME")
                               or a.startswith("${HOME}")
                               or a in (".", "..")
                               or prog in _BASH_CONTENT_READERS
                               or prog in _BASH_DIR_LISTERS)
            if looks_like_path:
                _add(a)

    try:
        import shlex
        for segment in _shell_segments(_strip_heredoc_bodies(cmd)):
            segment = segment.strip()
            if not segment:
                continue
            try:
                argv = shlex.split(segment, comments=True)
            except ValueError:
                argv = [w.strip("\"'") for w in segment.split()]
            argv, moved = walk.enter(segment, argv)
            # `make -C d`, `env -C d`, `git -C d`: this command's relative
            # names land in d; the next command is back in ``here``.
            if not moved:
                here = _known(walk.command_dir(argv))
            try:
                _segment_reads(argv, moved)
            finally:
                walk.leave()
                here = _known(walk.here)
    except Exception:
        return out
    return out


# Directories a command legitimately names even under a locked scope:
# interpreters, system binaries and libraries. They hold no user data,
# and refusing them would block `/usr/bin/env python3` rather than an
# escape attempt.
_SYSTEM_PATH_PREFIXES: tuple[str, ...] = (
    "/usr/", "/bin/", "/sbin/", "/lib/", "/lib64/", "/opt/", "/proc/self/",
)

# The pseudo-devices, named one by one rather than by a "/dev/" prefix.
#
# `2>/dev/null` is the commonest idiom in shell there is, and it was read
# as reaching outside the workspace through a link -- 58 refusals in the
# audit log, most of them a `find` or an `ls` with its errors silenced.
# Nothing is contained by refusing it: /dev/null discards what it is
# given and yields nothing when read.
#
# Named individually because a "/dev/" prefix would also exempt
# /dev/sda1, /dev/mem and every other real device, which is exactly the
# escape this check exists for. Each entry here carries no user data in
# either direction, or aliases a descriptor the process already holds.
_SAFE_DEVICES: frozenset[str] = frozenset({
    "/dev/null", "/dev/zero", "/dev/full",
    "/dev/random", "/dev/urandom",
    "/dev/tty", "/dev/stdin", "/dev/stdout", "/dev/stderr",
})
_SAFE_DEVICE_PREFIXES: tuple[str, ...] = ("/dev/fd/",)


def _is_safe_device(path: "str | Path") -> bool:
    """True for a pseudo-device that can neither leak nor import data."""
    text = str(path)
    return (text in _SAFE_DEVICES
            or text.startswith(_SAFE_DEVICE_PREFIXES))
# The same directories named without a trailing component ("ls /bin").
_SYSTEM_DIRS: frozenset[str] = frozenset(
    p.rstrip("/") for p in _SYSTEM_PATH_PREFIXES)


# ".." as a PATH SEGMENT — deliberately not a bare substring, so the
# brace range in `for i in {1..10}` and a float like 1..2 do not match.
_PARENT_SEGMENT_RE = re.compile(r"(?:^|[\s'\"=(:])\.\.(?:[/\\]|[\s'\")]|$)")


def _bash_climbs_out(cmd: str) -> bool:
    """True if a command walks up out of its directory.

    Inside a single locked folder ``..`` has no legitimate use: it aims
    either at the folder's parent or past it. This is what catches
    ``cd .. && cat ../other/file`` — a relative escape names no absolute
    path, so the path scanner never sees it. Filesystem isolation is the
    real containment; this is what stands in for it where bwrap does not
    run.
    """
    return bool(_PARENT_SEGMENT_RE.search(cmd or ""))


# Absolute-path-shaped runs anywhere in a command string. Not preceded
# by ':' or '/' so a URL's "//host/path" is not read as a path. Scanned
# over the RAW command rather than over shell tokens: an absolute path
# inside a quoted string — python3 -c "open('/etc/passwd')" — is a
# single token that does not begin with '/', which is exactly how the
# earlier read-refusal was circumvented in the field.
_ABS_PATH_RE = re.compile(r"(?<![:/\w])(~?/[\w.\-+/]*[\w.\-+])")


def _bash_paths_outside(cmd: str, workspace: Path) -> list[str]:
    """Absolute paths in *cmd* that point outside *workspace*.

    Coarser than the read/write scanners on purpose: under a locked scope
    the question is not what a command does with a path but whether it
    names one at all. System and interpreter directories are exempt.

    A candidate counts only when it — or its parent — exists on disk.
    That keeps `sed 's/a/b/'` and similar slash-shaped arguments from
    reading as paths, while still catching a write to a new file in an
    existing directory. Never raises: an unparseable command yields
    nothing rather than a false refusal, because filesystem isolation is
    the containment this backs up.
    """
    out: list[str] = []
    try:
        ws = str(Path(workspace).resolve())
        for match in _ABS_PATH_RE.finditer(cmd or ""):
            candidate = match.group(1)
            try:
                expanded = Path(candidate).expanduser()
            except Exception:
                continue
            text = str(expanded)
            if text.startswith(_SYSTEM_PATH_PREFIXES) or text in _SYSTEM_DIRS:
                continue
            if _is_safe_device(text):
                continue
            if text == ws or text.startswith(ws.rstrip("/") + "/"):
                continue
            try:
                if not (expanded.exists() or expanded.parent.exists()):
                    continue
            except OSError:
                continue
            if text not in out:
                out.append(text)
    except Exception:
        return out
    return out


# Path-shaped tokens, relative ones included. _ABS_PATH_RE only matches
# absolute paths, which is why a symlink was invisible: `cat link/x` names
# nothing absolute, so nothing looked at it.
_REL_PATH_RE = re.compile(r"(?<![\w/])([\w.][\w.\-]*(?:/[\w.\-]+)+/?)")


# Commands whose real target is not in the command text.
#
# The interpreter may be named through a PATH: `.venv/bin/python -c …` and
# `/usr/bin/python3 -c …` are the same capability as a bare `python -c`, and
# without the prefix group they read as an ordinary word to this regex — the
# venv fallback in ``_segment_auto_allowed`` then auto-allowed the first form
# even under a locked scope.
#
# The word boundary used to sit after the whole alternation, and one
# alternative ends in `=`. `env X=1 …` matched because `1` is a word
# character; `env PYTHONPATH=/elsewhere …` did not, because `/` is not —
# so the spelling that actually redirects an import was the spelling the
# guard could not see. Each alternative carries its own boundary now.
_INTERPRETER_RE = re.compile(
    r"(?:^|[;&|`$(]\s*)\s*"
    r"(?:[\w./~+-]*/)?"          # one flat group: no nested quantifier
    r"(?:"
    r"python[0-9.]*\s+-c\b|"
    # `python3 <<'EOF'` was already caught by the bare `<`; `python3 -
    # <<'EOF'`, which is how the form is actually written, was not — one
    # dash separated it from every gate. Flags between are bounded
    # repetition on purpose: the group above is flat "no nested
    # quantifier" for backtracking reasons and this one must not undo it.
    r"python[0-9.]*(?:\s+-[A-Za-z]{0,8}){0,3}\s*<|"
    r"perl\s+-e\b|ruby\s+-e\b|node\s+-e\b|php\s+-r\b|"
    r"(?:eval|exec|source|make|xargs)\b|\.\s|"
    r"env\s+[A-Za-z_][A-Za-z0-9_]*=|"
    r"base64\s+(?:-d|--decode)\b|"
    r"find\b[^;|&]*-exec\b"
    r")"
)

# Words that run the command that follows them. The regex above anchors
# an interpreter at the start of the command or after a shell operator,
# so one of these in front hid it completely: `time python3 -c "…"` was
# auto-allowed (`time` is on the auto-allow list) with the payload never
# looked at once. Same list as ``_referenced_script_paths`` uses for the
# same reason, and stripped repeatedly — `nohup time python3 -c` is two
# of them.
_EXEC_WRAPPER_WORD_RE = re.compile(
    r"^\s*(?:[A-Za-z_][A-Za-z0-9_]*=\S*\s+|"
    r"(?:env|nohup|time|timeout|nice|ionice|setsid|stdbuf|command|builtin|"
    r"watch|sudo|doas)\b(?:\s+-{1,2}[\w-]+(?:=\S+)?|\s+\d+(?:\.\d+)?[smhd]?)*"
    r"\s+)"
)


def _strip_exec_wrappers(segment: str) -> str:
    """Drop the wrapper words in front of the command a segment runs.

    `timeout 30 env FOO=bar python3 -c "…"` runs python. Peeling the
    wrappers is what lets the checks that anchor on the head of a command
    reach the command that is actually there.
    """
    prev, out = None, segment or ""
    while out != prev and len(out) < 100_000:
        prev = out
        out = _EXEC_WRAPPER_WORD_RE.sub("", out, count=1)
    return out


_REQUIRED_BY_TOOL: dict[str, tuple[str, ...]] | None = None

# Keys a tool accepts INSTEAD of the one its schema names. Weak models
# generate the neighbouring convention -- `file_path` for `path` is the
# commonest -- and ``_get_path_arg`` has tolerated that for as long as
# there have been weak models. A guard that reads the schema literally
# would take that tolerance away, so it reads it through this table.
_ARG_ALIASES: dict[str, tuple[str, ...]] = {
    "path": ("file_path", "filename", "file", "target"),
}

# (tool, parameter) pairs where an EMPTY value is the point of the call.
# Everywhere else an empty required argument is treated as an absent one,
# because that is how the silent-wrong-answer cases below arrived. Here it
# is content, not an identifier, and emptiness means something:
# `new_string: ""` deletes the block it matched, and `content: ""` creates
# an empty file. Both verified against the executor before this guard was
# added -- refusing them would have been a regression written in the name
# of a fix.
_EMPTY_IS_MEANINGFUL: frozenset[tuple[str, str]] = frozenset({
    ("edit_file", "new_string"),
    ("write_file", "content"),
})

# Required in the SCHEMA, because the model should send it, but never a
# reason to refuse the call. `description` is a line for the audit trail;
# the command runs the same without it. Failing an action over a missing
# label would turn a working call into a dead turn, which is the whole
# failure this guard exists to reduce -- so the schema keeps asking and
# the gate keeps quiet.
_LABEL_ONLY: frozenset[tuple[str, str]] = frozenset({
    ("bash", "description"),
    ("bash_background", "description"),
    ("subagent", "description"),
})

# Tools that carry their OWN plan-mode refusal in their body, past the
# entry gate. Both are on the plan-mode safe list -- reading a task list
# is fine -- and refuse deeper down because it is the STATUS change, not
# the tool, that starts execution.
#
# In plan mode they must answer with that reason, not with an argument
# nit: a model told "subject is required" for a task_create it may not
# perform learns the wrong thing and retries into the same wall. Same
# precedence argument as everywhere else in this chain -- the more
# permanent reason wins -- and it is the one case the entry gate cannot
# see, because from outside the tool looks allowed.
#
# The set is asserted against the source in
# tests/test_plan_mode_changes_nothing.py, so a third such tool cannot
# be added without this list being updated.
_PLAN_MODE_BODY_REFUSERS: frozenset[str] = frozenset({
    "task_create", "task_update",
})


_SCHEMA_BY_TOOL: Optional[dict[str, dict]] = None


def _stray_field_hint(name: str, arguments: dict) -> str:
    """" Unknown field 'pth' -- did you mean 'path'?" for fields the schema
    does not name, or "". Appended to a missing-field message: the
    misspelling is usually WHY the field is missing."""
    try:
        _malformed_arguments(name, {})            # fills the schema table
        schema = (_SCHEMA_BY_TOOL or {}).get(_bare_tool_name(name)) or {}
        props = list((schema.get("properties") or {}))
        aliases = {a for group in _ARG_ALIASES.values() for a in group}
        hints = []
        for key in arguments or {}:
            if key in props or key in aliases:
                continue
            best = _tool_args._suggestion(key, props)
            if best:
                hints.append(f"unknown field '{key}' -- did you mean '{best}'?")
        return (" " + " ".join(hints)) if hints else ""
    except Exception:
        return ""


def _malformed_arguments(name: str, arguments: dict) -> Optional[str]:
    """The schema's answer to a call it cannot accept, or None.

    Runs after _missing_required_argument, which keeps its own policy
    (label-only and empty-is-meaningful fields, aliases). This adds what
    it never looked at: types and shapes (``edits`` sent as a string),
    enum values, and the two safe repairs -- a JSON string holding the
    object or list the schema wants, and a quoted integer -- which are
    applied to ``arguments`` in place. Extra fields pass: models send
    harmless ones, and refusing a working call over one would be a
    regression. They are only named when they explain a missing field.
    """
    global _SCHEMA_BY_TOOL
    try:
        if not isinstance(arguments, dict):
            return None
        if _SCHEMA_BY_TOOL is None:
            _SCHEMA_BY_TOOL = {
                (tool.get("function") or {}).get("name"):
                    (tool.get("function") or {}).get("parameters") or {}
                for tool in _DOC_TOOLS_OPENAI}
        bare = _bare_tool_name(name)
        schema = _SCHEMA_BY_TOOL.get(bare)
        if not schema:
            return None
        props = schema.get("properties") or {}
        # Read the call the way the executor will: an alias stands for its
        # field, and the checks _missing_required_argument waived stay
        # waived.
        probe = dict(arguments)
        alias_of: dict[str, str] = {}
        for field_name, aliases in _ARG_ALIASES.items():
            if field_name in props and field_name not in probe:
                for alias in aliases:
                    if alias in probe:
                        probe[field_name] = probe.pop(alias)
                        alias_of[field_name] = alias
                        break
        required = [r for r in schema.get("required") or []
                    if (bare, r) not in _LABEL_ONLY]
        result = _tool_args.check({**schema, "required": required}, probe,
                                  unknown="hint")
        if not result.ok:
            return (f"{result.error_text}. The call was not run -- re-send "
                    f"{bare} with arguments of that shape.")
        for key, value in result.args.items():
            arguments[alias_of.get(key, key)] = value
    except Exception:
        return None
    return None


# Keys a model sends the patch under besides the schema's ``diff``:
# ``patch`` and ``input`` are what the *** Begin Patch tool of GPT-family
# models calls it.
_PATCH_KEYS: tuple[str, ...] = ("patch", "input")


def _canonical_patch_arguments(arguments: Any, perms: Any) -> Optional[str]:
    """Bring an apply_patch call to the one shape everything downstream
    reads: a unified diff under ``diff``. Mutates *arguments* in place, so
    the gate, the approval preview, the journal and the post-turn verify
    harvest all see the diff that is applied. Returns an error message
    when an envelope cannot be translated, else None.

    Measured 2026-10-19: gpt-5-nano sent six envelopes under ``patch`` in
    one session; each was answered "diff is required", which it never
    connected to the key name, and the user's game was never changed.
    """
    if not isinstance(arguments, dict):
        return None
    if not str(arguments.get("diff") or "").strip():
        for key in _PATCH_KEYS:
            if str(arguments.get(key) or "").strip():
                arguments["diff"] = arguments.pop(key)
                break
    text = arguments.get("diff")
    if not isinstance(text, str):
        return None
    from . import patch_apply as _pa
    if not _pa.is_envelope(text):
        return None
    ws = getattr(perms, "workspace", None)
    if ws is None:
        return None          # no workspace: the executor refuses the call

    def _read(rel: str) -> Optional[str]:
        root = Path(ws).resolve()
        path = (root / rel).resolve()
        try:
            path.relative_to(root)
        except ValueError:
            raise ValueError(f"{rel} is outside the workspace")
        if _is_secret_path(perms, path):
            raise ValueError(f"{rel} matches a secret deny-glob")
        if not path.exists():
            return None
        return path.read_text(encoding="utf-8")

    try:
        arguments["diff"] = _pa.envelope_to_unified(text, _read)
    except (ValueError, OSError, UnicodeDecodeError) as exc:
        return (f"apply_patch could not use this *** Begin Patch envelope: "
                f"{exc}. Nothing was changed. Fix the envelope, or use "
                "edit_file (old_string/new_string) for this change.")
    return None


def _missing_required_argument(name: str, arguments: dict) -> Optional[str]:
    """The message for a required argument that never arrived, or None.

    One check at the single entry point rather than per tool, because per
    tool it was not there. Swept over the whole catalogue on 2026-09-09 by
    calling every tool with no arguments at all:

    * ``get_calc_info`` returned a real calculation -- the first in the
      index -- with its functional, basis set and energies. A model that
      spells the key `id` instead of `calc_id` (which I have done three
      times myself) gets a confident, complete answer about somebody
      else's run, and the grounding rules then have it cite those numbers.
      Not a refusal, not an error: plausible data about the wrong subject,
      which is the worst thing a scientific tool can hand back.
    * ``search_docs`` answered ``results: []`` beside the corpus
      statistics, which reads as "1539 sections searched, nothing on your
      topic" -- a negative finding about the documentation, from a search
      that was never made.
    * ``list_files`` listed the whole tree: a required ``pattern``
      silently defaulting to everything.
    * ``list_sections`` / ``read_section`` answered "Document '' not
      found" and printed every document id in the index.
    * ``history_get`` / ``history_search`` blamed the session for a
      missing ``ref`` / ``query``.

    Same shape as cron_delete answering "not_found" for a missing
    entry_id: the model is told the world is a certain way, when what
    happened is that its call was malformed. Empty string counts as
    missing -- that is how every one of the above arrived.

    Tools whose own message already names the argument are unaffected;
    they simply never reach their body with it absent.
    """
    global _REQUIRED_BY_TOOL
    try:
        if _REQUIRED_BY_TOOL is None:
            table: dict[str, tuple[str, ...]] = {}
            for tool in _DOC_TOOLS_OPENAI:
                fn = tool.get("function") or {}
                req = (fn.get("parameters") or {}).get("required") or []
                if fn.get("name") and req:
                    table[fn["name"]] = tuple(str(r) for r in req)
            _REQUIRED_BY_TOOL = table
        required = _REQUIRED_BY_TOOL.get(name)
        if not required or not isinstance(arguments, dict):
            return None
        for key in required:
            if (name, key) in _LABEL_ONLY:
                continue
            names = (key,) + _ARG_ALIASES.get(key, ())
            if (name, key) in _EMPTY_IS_MEANINGFUL:
                if any(arguments.get(k) is not None for k in names):
                    continue
            elif any(_argument_present(arguments.get(k)) for k in names):
                continue
            return (
                f"{key} is required for {name}, and none arrived. This is "
                f"about the call, not about the data: nothing was looked "
                f"up. Re-send it with {key} set."
            )
    except Exception:
        return None
    return None


def _argument_present(value: Any) -> bool:
    """Whether an argument carries something to act on.

    ``0`` and ``False`` do (``cell_idx: 0`` is a real cell); an empty
    string, an empty list and None do not.
    """
    if value is None:
        return False
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, (list, tuple, dict, set)):
        return bool(value)
    return True


def _is_interpreter_invocation(cmd: str) -> bool:
    """True when the command's real target cannot be read from its text.

    Not a judgement about danger -- `python -c "print(1)"` is harmless. It
    is a judgement about VISIBILITY: a scanner that decides on the command
    string cannot decide about these, so they belong in front of the user
    rather than on the auto-allow list.
    """
    try:
        text = cmd or ""
        # Read as the shell reads it: a `|xargs` or `|python` inside a
        # quoted grep pattern is a character, not a pipe (asked on
        # 2026-09-25 for `grep -n "awk\|xargs" f`).
        if _INTERPRETER_RE.search(_shell_visible(text)):
            return True
        # ...and again with the wrapper words peeled off each segment, so
        # `time python3 -c "…"` is the interpreter it is rather than an
        # auto-allowed `time`.
        for seg in _split_shell_segments(text):
            stripped = _strip_exec_wrappers(seg)
            if stripped != seg and _INTERPRETER_RE.search(
                    _shell_visible(stripped)):
                return True
        # A pipe into a shell or an interpreter: `... | bash`, `... | python3`.
        return bool(re.search(
            r"\|\s*(?:ba|z|k|da)?sh\b|\|\s*python[0-9.]*\b",
            _shell_visible(text)))
    except Exception:
        return True


# A segment that is nothing but `python -c <payload>`: the interpreter
# name (a bare word, so no PATH prefix and no `env FOO=1` in front),
# option flags, `-c`, and the payload. Anything else in the segment --
# a wrapper, a variable assignment, a pipe -- means the segment is
# opaque for a reason this module is not modelling, and the readable
# path below must not be taken for it.
_PLAIN_C_HEAD_RE = re.compile(r"^\s*python[0-9.]*\s")


def _inline_payload_is_readable(segment: str, workspace: Path | str) -> bool:
    """True when a segment's only opacity is a payload that can be read.

    `python -c` hides nothing: the program is a literal in the command
    line. This asks :mod:`delfin.agent.inline_payload` whether the whole
    payload can be accounted for, and answers False for everything else
    -- a payload with a construct the analyser does not model, a second
    reason the segment is opaque (`env X=1 python -c …`, `… | python3`),
    a command line that will not tokenise.

    A payload that WRITES stays off this path even when it is perfectly
    readable, and that is a policy choice rather than a limit of the
    analysis. Its target is now visible to ``_bash_write_targets`` and
    would be gated there like any other -- but over the 199 recorded
    auto-allow refusals not one payload wrote anything, so allowing them
    buys no measured friction back and spends the clearest security
    property this rule has. The write side of the analysis earns its
    keep in the gate, not here.

    Being wrong in the False direction costs a confirmation, which is
    what happens today for every one of these. Being wrong in the True
    direction would run something unread, so every unknown answers False.
    """
    try:
        seg = segment or ""
        if not _PLAIN_C_HEAD_RE.match(seg):
            return False
        payloads = _inline_payload.extract_c_payloads(seg)
        if payloads is None:
            return False
        # A here-document carries the same property `-c` does: with a
        # QUOTED delimiter the body is literal, so the text analysed is
        # the text the interpreter receives. `python3 - <<'EOF' … EOF`
        # is the third-largest group in the denial log (29 of 437) and
        # was refused for punctuation.
        #
        # Quoted only, and that is the whole argument. A bare `<<EOF` is
        # expanded by the shell first, so `$(…)` inside it means the
        # analysed text is NOT what runs — and being wrong here runs
        # something unread. `extract_stdin_payloads` defaults to quoted
        # for exactly this reason; the write gate is the only caller that
        # passes include_expanded, because it refuses rather than grants.
        heredocs = _inline_payload.extract_stdin_payloads(seg)
        payloads = list(payloads) + heredocs
        if not payloads:
            return False
        try:
            cwd: Path | None = Path(workspace)
        except (TypeError, ValueError):
            cwd = None
        for src in payloads:
            eff = _inline_payload.analyze_payload(src, cwd)
            if not eff.readable or eff.writes:
                return False
            # A read of an absolute path is somebody else's file. The
            # read gate catches it separately, but this predicate is what
            # decides whether the confirm veto fires AT ALL, so it cannot
            # call such a payload fully accounted for. Found by a test:
            # `print(open('/etc/passwd').read())` was reported readable
            # because only writes were being looked at.
            if any(t.startswith("/") or t.startswith("~")
                   for t in eff.reads):
                return False
        # The payloads are readable; the segment must be nothing BUT
        # them. Blank each one out and require what is left to be an
        # ordinary command again -- that is what rules out a second,
        # unmodelled reason for the segment's opacity.
        rest = seg
        for src in payloads:
            rest = rest.replace(src, " ", 1)
        # The redirect itself is punctuation, not a second command: what
        # is left of `python3 - <<'EOF'  EOF` has to read as an ordinary
        # invocation for the check below to mean anything.
        rest = re.sub(r"<<-?\s*(['\"]?)\w+\1", " ", rest)
        return not _is_interpreter_invocation(rest.replace("-c", " ", 1))
    except Exception:
        return False


def _bash_symlink_escapes(cmd: str, workspace: Path) -> list[str]:
    """Tokens in *cmd* that RESOLVE outside *workspace*.

    The absolute-path scanner reads the command as written. A symlink
    inside the folder pointing out of it is written as an ordinary
    relative path, so `cat shared/personal.xlsx` looked local and was not,
    and `cd shared && cat x` walked out without a single `..`.

    A symlink into a department share is a normal thing to find in an
    office folder, which is what makes this the escape a model reaches by
    accident rather than on purpose.

    Only tokens that exist are considered, and only ones that actually
    move: a path resolving to where it appeared to point is not reported.
    """
    out: list[str] = []
    try:
        ws = Path(workspace).resolve()
    except OSError:
        return out
    seen: set[str] = set()
    try:
        text = cmd or ""
        candidates = [m.group(1) for m in _REL_PATH_RE.finditer(text)]
        candidates += [m.group(1) for m in _ABS_PATH_RE.finditer(text)]
        # A bare directory name has no slash, so the patterns above miss it.
        # `cd shared && cat x` needs no `..` and names nothing absolute, and
        # every command after it is then evaluated somewhere else entirely.
        candidates += re.findall(
            r"(?:^|[;&|(]\s*)(?:cd|pushd)\s+([^\s;&|<>()]+)", text)
        # A relative name is opened where the shell is at that point:
        # `cd sub && cat d/link` opens sub/d/link. Each directory the
        # command moves into is tried (_bash_visited_dirs).
        # Directories outside the folder are the absolute-path and `..`
        # checks' to refuse; joining a name to one would report a plain
        # outside file as a link.
        bases = [b for b in _bash_visited_dirs(text, ws)
                 if (os.path.normpath(str(b)) + "/").startswith(str(ws) + "/")]
        bases = bases or [ws]
        for token in candidates:
            if token in seen:
                continue
            seen.add(token)
            try:
                raw = Path(token).expanduser()
            except (OSError, RuntimeError):
                continue
            for base in ([ws] if raw.is_absolute() else bases):
                try:
                    joined = raw if raw.is_absolute() else (base / raw)
                    if not (joined.exists() or joined.parent.exists()):
                        continue
                    resolved = joined.resolve()
                except (OSError, RuntimeError):
                    continue
                if str(resolved).startswith(_SYSTEM_PATH_PREFIXES):
                    continue
                if _is_safe_device(resolved) or _is_safe_device(token):
                    continue
                if resolved == ws or str(resolved).startswith(str(ws) + "/"):
                    continue
                out.append(f"{token} -> {resolved}")
                break
    except Exception:
        return out
    return out


def _uncommitted_note(workspace) -> str:
    """One line when a turn leaves changes nobody committed, else "".

    Four sessions on 2026-09-18 produced four commits between them, each
    at the very end, and 226 tool calls went into one of them. The one
    session that committed in two steps -- the failing control first,
    then the fix -- was the one whose work could be verified in a minute,
    because the order was the evidence. Two full suites were killed
    mid-session the same day by a node watchdog: what is committed
    survives that, and what is not hangs by a thread.

    A line, not a demand: it says what is there and stops. Never raises,
    and says nothing outside a git checkout.
    """
    if not workspace:
        return ""
    try:
        out = safe_git.run(["status", "--porcelain"], workspace, timeout=5)
        if out.returncode != 0:
            return ""                     # not a checkout: nothing to say
        changed = [ln for ln in out.stdout.splitlines()
                   if ln.strip() and not ln.startswith("?? ")]
        if not changed:
            return ""
        n = len(changed)
        return (f"[git] {n} tracked file{'s' if n != 1 else ''} changed and "
                "not committed. A step that stands on its own is worth a "
                "commit now — a control run that fails, committed before "
                "the fix that makes it pass, is the one commit that proves "
                "the most.")
    except Exception:
        return ""


def _bash_write_targets(cmd: str) -> list[str]:
    """Paths a shell command would plausibly WRITE to.

    Best-effort and conservative: it recognises redirections, the common
    file-creating commands and destination options. It is a second line of
    defense that turns an out-of-workspace write into a clear refusal —
    the airtight containment is filesystem isolation
    (``agent.bash_isolation``), which this does not replace. Never raises;
    an unparseable command yields no targets rather than a false block.

    A ``python -c`` payload is read as Python for the same question, so
    ``open('out.csv', 'w')`` is a target here exactly as ``tee out.csv``
    is. Before that, a write through python was the one file-creating
    form this function could not see at all -- which is half of why an
    interpreter had to be kept off the auto-allow list wholesale.
    """
    targets: list[str] = []
    try:
        import shlex

        def _add(tok: str) -> None:
            tok = (tok or "").strip()
            # Quotes are shell syntax anywhere in the word, not only at its
            # ends. Stripping the ends left `"dir"/file` as `dir"/file` --
            # a path that exists nowhere, so a directory the user had
            # GRANTED came back "outside what you may modify". Measured:
            # dir/file and "dir/file" passed, "dir"/file and 'dir'/file
            # were refused, which punishes exactly the careful quoting a
            # model writes around a variable. shlex reads the word the way
            # the shell will; anything it cannot read as ONE word is left
            # alone, because guessing wider is how a gate stops gating.
            if "'" in tok or '"' in tok:
                try:
                    parts = shlex.split(tok)
                except ValueError:
                    parts = []
                if len(parts) == 1:
                    tok = parts[0]
                else:
                    tok = tok.strip("'\"")
            if not tok or tok.startswith("-") or tok.startswith("$"):
                return
            if any(c in tok for c in "*?[]"):        # globs: not a literal path
                return
            # A relative target after `cd` lands where cd went. The read
            # scanner has followed cd/pushd for a while; this one resolved
            # `cd /x && printf y > f` to `f` -- against the gate's own cwd,
            # inside the workspace -- so the write to /x/f was never seen.
            # Where filesystem isolation stands that is a dead end; where
            # only this scanner stands (the Claude CLI backend's hook) it
            # was a way to write anywhere, the hook's own state included.
            if here is not None and not (tok.startswith("/") or tok.startswith("~")):
                tok = str(here / tok)
            targets.append(tok)

        # The directory the shell is in, per segment: None until a `cd`
        # names one. After a `cd $VAR`, a `cd` into a variable-built path or
        # a `cd -` with no known previous, it is UNRESOLVED -- and a
        # relative write from there is reported under a path that cannot be
        # inside any root, so the gate refuses it. The read scanner stops
        # inspecting relatives at that point; for writes that would be the
        # open direction, and "could not tell where this writes" is a
        # refusal, not a pass.
        here = None
        _env = _scrubbed_bash_env()
        walk = _ShellDirWalk(None, env=_env, cmd=cmd)

        def _enter(segment: str, argv: list) -> tuple:
            """Follow one simple command (_ShellDirWalk). A subshell the
            previous command closed is closed first, so `(cd /x) && > f`
            writes where the command began. Returns (argv, moved)."""
            nonlocal here
            walk.leave()
            argv, moved_ = walk.enter(segment, argv)
            here = walk.here
            return argv, moved_

        # Redirections: > file, >> file, 2> file, &> file (not >&1 / &2) --
        # per segment, so the directory a `cd` set applies to them.
        _redirect = re.compile(r"(?<![0-9<>&])(?:[0-9]?|&)>{1,2}\s*([^\s;&|<>()]+)")
        # `>&file` and `>| file` write a file too, but their `&` and `|`
        # would split the segment in two below and the target would be lost.
        # `>&2`, `>&-` and `2>&1` duplicate a descriptor and stay as they are.
        _scan = re.sub(
            r">&(?!\s*(?:\d+|-)(?=[\s;&|)]|$))\s*|>\|\s*", "> ", cmd)
        # A `>` inside quotes is text only for a program that does not
        # run its argument: `bash -c '... > f'`, `eval "... > f"` and
        # `awk '{print > "f"}'` write that file, and so does a command
        # substitution. The spans are found on the whole command, quotes
        # and here-documents read as the shell reads them, because the
        # split below ignores quotes and cuts `"a;b"` in two.
        _text = _quoted_text_spans(_scan)
        # In the quoted code of a non-shell interpreter a `>` touching `=`
        # or following `-` is that language's operator (`>=`, `>>=`, `->`,
        # `=>`, `<=>`): no shell parses that text, and the name after it is
        # an operand, not a file. A bare `>` there is still reported, since
        # `os.system('echo x > f')` writes f. A shell's argument (`bash -c`,
        # `eval`) is re-parsed by that shell, so `>=` there -- like `>=`
        # unquoted -- stays a redirect to a file named `=`.
        _code = _quoted_text_spans(_scan, owners=_CODE_INTERPRETERS)
        # An awk program's `>` writes only to a string expression: `print >
        # "f"` or `print > name`. Anything else after it is awk syntax --
        # `/<\/script>/{f=0}` is the end of a regex and a block, `>=` a
        # comparison -- and reporting `/{f=0}` as a write outside the
        # workspace refused every awk that matched an HTML closing tag
        # (measured 2026-10-19: two syntax checks of a game, both refused).
        _awk = _quoted_text_spans(_scan, owners=_AWK_PROGRAMS)
        _cuts = [0]
        for _sep in re.finditer(r"[;&|]{1,2}|\n", _scan):
            _cuts += [_sep.start(), _sep.end()]
        _cuts.append(len(_scan))
        for _k in range(0, len(_cuts), 2):
            segment = _scan[_cuts[_k]:_cuts[_k + 1]]
            seg = segment.strip()
            if not seg:
                continue
            _off = _cuts[_k] + len(segment) - len(segment.lstrip())
            try:
                argv0 = shlex.split(seg, comments=True)
            except ValueError:
                argv0 = seg.split()
            if _enter(seg, argv0)[1]:
                continue
            for m in _redirect.finditer(seg):
                if any(lo <= _off + m.start() < hi for lo, hi in _text):
                    continue    # `>` inside quotes is text, not a redirection
                _op = re.search(r">{1,2}", m.group(0))
                _gt = _off + m.start() + _op.start()
                _past = _off + m.start() + _op.end()
                if (any(lo <= _gt < hi for lo, hi in _code)
                        and (_scan[_gt - 1:_gt] in ("-", "=")
                             or _scan[_past:_past + 1] == "=")):
                    continue    # an operator of the interpreted language
                if (any(lo <= _gt < hi for lo, hi in _awk)
                        and (_scan[_gt - 1:_gt] in ("-", "=", "<")
                             or not re.match(r"""[\s>]*["'A-Za-z_$]""",
                                             _scan[_past:]))):
                    continue    # awk syntax, not an output redirection
                tok = m.group(1)
                if not tok.startswith("&"):
                    _add(tok)
        here = None
        walk = _ShellDirWalk(None, env=_env, cmd=cmd)

        # What an inline python payload would write.
        #
        # Here-documents are included, and with include_expanded=True.
        # `python3 - <<'EOF' … EOF` is `python -c` with different
        # punctuation, and it was invisible here: a body of
        # `open('/etc/evil','w').write('x')` produced no write target at
        # all. An unquoted `<<EOF` is shell-expanded before the
        # interpreter sees it, so the text read here is not necessarily
        # the text that runs — but this path REFUSES on what it finds, so
        # scanning an expandable body can only block more, never allow
        # more. That argument does not hold on a path that grants, and
        # `_inline_payload_is_readable` accordingly takes quoted bodies
        # only.
        #
        # A relative payload target is resolved where the interpreter
        # starts: the command is tokenised once with quotes honoured
        # (a multi-line `-c` string stays one word), cut into commands at
        # `; & | && || newline`, and `cd`/`pushd` are followed in order.
        # A `-c` payload takes the directory of its own command; the n-th
        # python here-document opener takes the directory at that opener.
        # Where that pairing cannot be made (the tokeniser fails, or the
        # counts differ) a command that contains a `cd` reports relative
        # targets as unresolved, so the gate refuses rather than guesses.
        here = None
        walk = _ShellDirWalk(None, env=_env, cmd=cmd)
        _c_dirs: list = []           # (payload, directory)
        _doc_dirs: list = []
        _paired = True
        try:
            _lx = shlex.shlex(cmd, posix=True, punctuation_chars=";&|\n")
            _lx.whitespace = " \t\r"
            _lx.whitespace_split = True
            _toks = list(_lx)
        except ValueError:
            _toks, _paired = [], False
        _cmds: list = [[]]
        for _t in _toks:
            if _t and all(ch in ";&|\n" for ch in _t):
                _cmds.append([])
            else:
                _cmds[-1].append(_t)
        for _argv in _cmds:
            _, _mv = _enter(" ".join(_argv), list(_argv))
            if _mv or not _argv:
                continue
            # `env -C d python3 -c …` starts the interpreter in d.
            _where = walk.command_dir(_argv)
            for src in _inline_payload.extract_c_payloads(
                    shlex.join(_argv)) or []:
                _c_dirs.append((src, _where))
            if (any(re.match(r"(?:[\w./~+-]*/)?python[0-9.]*$", w)
                    for w in _argv)
                    and any(w.startswith("<<") and not w.startswith("<<<")
                            for w in _argv)):
                _doc_dirs.append(_where)
        _fallback = _UNRESOLVED_DIR if (
            len(walk.visited) > 1
            or re.search(r"(?:^|[\s;&|(])(?:cd|pushd|popd)(?:\s|$)", cmd)) \
            else None
        _c_srcs = list(_inline_payload.extract_c_payloads(cmd) or [])
        _docs = _inline_payload.extract_stdin_payloads(
            cmd, include_expanded=True)
        # The whole-command split glues an unquoted `;` to the word before
        # it (`"open('a','w')";` -> `open('a','w');`), so the per-command
        # payloads are the exact ones; the whole-command list only checks
        # that none was lost, and on a difference both are read, unpaired.
        if not _paired or len(_c_dirs) != len(_c_srcs):
            _c_dirs = [(s, _fallback)
                       for s in _c_srcs + [s for s, _ in _c_dirs]]
        if not _paired or len(_doc_dirs) != len(_docs):
            _doc_dirs = [_fallback] * len(_docs)
        for src, where in _c_dirs + list(zip(_docs, _doc_dirs)):
            here = where
            for tok in _inline_payload.analyze_payload(src).writes:
                _add(tok)
        here = None
        walk = _ShellDirWalk(None, env=_env, cmd=cmd)

        # Per shell segment: command name + arguments.
        for segment in re.split(r"[;&|]{1,2}|\n", cmd):
            segment = segment.strip()
            if not segment:
                continue
            try:
                argv = shlex.split(segment, comments=True)
            except ValueError:
                argv = segment.split()
            if not argv:
                continue
            argv, _mv = _enter(segment, argv)
            if _mv:
                continue
            # Skip env-var prefixes (FOO=bar cmd ...).
            while argv and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", argv[0]):
                argv = argv[1:]
            if not argv:
                continue
            name = Path(argv[0]).name
            rest = argv[1:]

            # `cd <dir> && ...` — the destination of the segment's writes.
            if name in ("dd",):
                for a in rest:
                    if a.startswith("of="):
                        _add(a[3:])
                continue
            if name in ("python", "python3") and "venv" in rest:
                # python -m venv <dir>
                tail = [a for a in rest[rest.index("venv") + 1:]
                        if not a.startswith("-")]
                if tail:
                    _add(tail[0])
                continue
            if (name in ("python", "python3") or name.startswith("python3.")) \
                    and "ensurepip" in rest:
                # `python -m ensurepip` writes pip into an environment, and
                # it names no path on the command line -- so this scanner
                # found no target, the write gate had nothing to refuse,
                # and the command ran. Measured by driving the executor on
                # 2026-10-08: of six home-directory writes, five were
                # refused and `python3 -m ensurepip --user` returned
                # exit 0.
                #
                # --user is the form that leaves the interpreter's own
                # tree: it installs into the per-user site directory, which
                # no workspace root covers. Asked of `site`, not written
                # as "~/.local" -- the location is the interpreter's
                # answer and differs per platform.
                if "--user" in rest:
                    try:
                        import site as _site
                        _add(_site.getuserbase())
                    except Exception:
                        _add("~/.local")
                # Without --user it writes inside the environment's own
                # prefix, which is either the workspace (fine) or a path
                # the venv target rule above already covers.
                continue
            if name in ("virtualenv", "uv") and rest:
                tail = [a for a in rest if not a.startswith("-")]
                if tail:
                    _add(tail[-1])
                continue
            if name == "git" and len(rest) >= 2 and rest[0] == "clone":
                pos = [a for a in rest[1:] if not a.startswith("-")]
                if len(pos) >= 2:
                    _add(pos[-1])
                continue
            if name in ("sed", "perl") and any(
                    a.startswith("-i") for a in rest):
                pos = [a for a in rest if not a.startswith("-")]
                # First positional is the script unless -e/-f supplied it.
                if not any(a.startswith(("-e", "-f")) for a in rest):
                    pos = pos[1:]
                for a in pos:
                    _add(a)
                continue
            if name == "ln":
                pos = [a for a in rest if not a.startswith("-")]
                if len(pos) >= 2:
                    _add(pos[-1])
                continue

            # Destination-carrying options (pip --target, tar -C, ...).
            # Short ones are suppressed for commands where they mean
            # something else -- see _BASH_NO_DEST_OPTS.
            for i, a in enumerate(rest):
                if a in _BASH_DEST_OPTS and i + 1 < len(rest):
                    # Only -C, and only for a git that reads: a write
                    # option on a reading subcommand still counts, so
                    # `git diff --output=/etc/x` remains a target.
                    if (a == "-C" and name == "git"
                            and _git_reads_only(rest)):
                        continue
                    if _dest_opt_applies(name, a):
                        _add(rest[i + 1])
                elif "=" in a and a.split("=", 1)[0] in _BASH_DEST_OPTS:
                    if _dest_opt_applies(name, a.split("=", 1)[0]):
                        _add(a.split("=", 1)[1])

            pos = [a for a in rest if not a.startswith("-")]
            if name in _BASH_DEST_ALL:
                for a in pos:
                    _add(a)
            elif name in _BASH_DEST_LAST and len(pos) >= 2:
                _add(pos[-1])
    except Exception:
        return []
    # De-duplicate, preserve order. Scratch sinks are filtered by the
    # caller, which knows the workspace (a workspace may legitimately live
    # under /tmp, and then its files are not scratch).
    out: list[str] = []
    seen: set[str] = set()
    for t in targets:
        if t not in seen:
            seen.add(t)
            out.append(t)
    return out


# Commands that only ever READ the files named on their command line.
# Anything that can write, execute, or take a program on stdin stays out:
# what this set buys is evidence, and evidence must not be minted by a
# command whose effect nobody checked.
_BASH_READERS = frozenset({
    "cat", "head", "tail", "grep", "egrep", "fgrep", "rg", "ag",
    "awk", "gawk", "mawk", "nl", "wc", "sort", "uniq", "cut", "tac",
    "od", "xxd", "strings", "jq", "column", "diff", "cmp", "md5sum",
    "sha256sum", "file", "stat", "less", "more", "zcat", "zgrep",
})


def _bash_read_targets(cmd: str, cwd: Path | None = None) -> list[str]:
    """Files a shell command demonstrably READ, as absolute paths.

    The counterpart to :func:`_bash_write_targets`, and it exists for the
    grounding guards rather than for the gate. Those guards judge an
    answer against a ledger of files the session looked at, and the ledger
    was fed only by the typed tools — so a session whose data lives
    outside the workspace and is read with ``grep`` through the shell
    produced an EMPTY ledger while the guards still ran against it. In the
    field that turned a correct answer into a forced correction turn: nine
    ORCA outputs grepped, the answer citing ``S1.out`` and ``T1.out``, and
    the citation check resolving those names against the repo root,
    finding nothing, and reporting them as invented.

    A cited basename clears against an absolute entry here because
    ``verify_guard._is_observed`` matches on suffix.

    Disambiguation is by EXISTENCE, not by each tool's flag grammar: a
    token is recorded when it resolves to a real file. ``grep PATTERN
    file.out`` therefore records the file and not the pattern, without
    this function having to know where grep's pattern sits. The residual
    risk is a pattern that happens to name an existing file, which grounds
    one extra path — bounded, and the direction that fails safe.

    Globs are skipped rather than expanded: expanding one would record
    files the command may never have opened.

    Never raises; an unparseable command yields nothing.
    """
    found: list[str] = []
    try:
        import shlex

        for segment in _split_shell_segments(cmd):
            segment = segment.strip()
            if not segment:
                continue
            try:
                argv = shlex.split(segment, comments=True)
            except ValueError:
                continue
            while argv and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", argv[0]):
                argv = argv[1:]
            if not argv:
                continue
            if Path(argv[0]).name not in _BASH_READERS:
                # An unrecognised segment contributes nothing. A compound
                # command is only as trustworthy as its least understood
                # part, and here that costs a missing entry, never a
                # wrong one.
                continue
            for tok in argv[1:]:
                tok = tok.strip()
                if (not tok or tok.startswith("-") or tok.startswith("$")
                        or "=" in tok.split("/")[0]
                        or any(c in tok for c in "*?[]")):
                    continue
                try:
                    p = Path(tok)
                    if not p.is_absolute():
                        if cwd is None:
                            continue
                        p = cwd / p
                    if p.is_file():
                        found.append(str(p.resolve()))
                except OSError:
                    continue
    except Exception:
        return []
    out: list[str] = []
    seen: set[str] = set()
    for t in found:
        if t not in seen:
            seen.add(t)
            out.append(t)
    return out


def _is_ephemeral_sink(path: Path, workspace: Path | None) -> bool:
    """True for device sinks and scratch space OUTSIDE the workspace.

    Gating these would only produce noise: they hold no user data. A
    workspace that itself lives under a scratch root keeps full gating.
    """
    try:
        text = str(path)
        if text.startswith("/dev/") or text == "/dev/null":
            return True
        if not (text in _BASH_SCRATCH_EXACT
                or text.startswith(_BASH_SCRATCH_PREFIXES)):
            return False
        # A workspace that itself lives under scratch space makes scratch
        # and work indistinguishable — gate everything in that setup.
        if workspace is not None:
            ws = str(Path(workspace).resolve())
            if ws in _BASH_SCRATCH_EXACT or ws.startswith(
                    _BASH_SCRATCH_PREFIXES):
                return False
        return True
    except Exception:
        return False


def _host_process_ancestry() -> list[tuple[int, str, str]]:
    """[(pid, name, cmdline)] for this process and its ancestors.

    The agent's session runs INSIDE a host stack (Voila server -> Jupyter
    kernel, or a terminal session); a broad process-kill that matches an
    ancestor kills the very UI hosting the agent (observed in the field:
    ``pkill -f "voila.*8866"`` took down the user's dashboard mid-turn,
    losing the whole unpersisted turn). Linux /proc walk; empty list when
    unavailable. Never raises.
    """
    out: list[tuple[int, str, str]] = []
    try:
        pid = os.getpid()
        for _ in range(32):
            with open(f"/proc/{pid}/stat", encoding="utf-8",
                      errors="replace") as fh:
                stat = fh.read()
            comm = stat[stat.index("(") + 1:stat.rindex(")")]
            ppid = int(stat[stat.rindex(")") + 2:].split()[1])
            try:
                cmdline = (Path(f"/proc/{pid}/cmdline").read_bytes()
                           .replace(b"\0", b" ").decode(errors="replace")
                           .strip())
            except OSError:
                cmdline = ""
            out.append((pid, comm, cmdline))
            if ppid <= 1:
                break
            pid = ppid
    except Exception:
        return []
    return out


# Host stacks DELFIN sessions are known to run under — the conservative
# fallback when /proc ancestry is unavailable.
_HOST_STACK_RE = re.compile(r"(?i)\b(?:voila|jupyter|ipykernel)\b")


def _kill_targets_host_process(
    command: str,
    ancestry: list[tuple[int, str, str]] | None = None,
) -> str:
    """Reason string when ``command`` would kill this session's host
    process (pkill/killall pattern or kill PID matching an ancestor),
    else "". Precise where /proc is readable; falls back to blocking
    kill patterns naming known host stacks. Never raises."""
    try:
        if not re.search(r"(?:^|[;&|(\s])(?:pkill|killall|kill)\b", command):
            return ""
        anc = _host_process_ancestry() if ancestry is None else ancestry
        for m in re.finditer(
                r"(?:^|[;&|(]\s*)\s*(pkill|killall|kill)\b([^;&|)]*)",
                command):
            tool, rest = m.group(1), m.group(2)
            try:
                import shlex
                argv = shlex.split(rest)
            except Exception:
                argv = rest.split()
            flags = [a for a in argv if a.startswith("-")]
            args = [a for a in argv if not a.startswith("-")]
            if tool == "kill":
                pids = {int(a) for a in args if a.isdigit()}
                hit = [a for a in anc if a[0] in pids]
                if hit:
                    return (f"kill {hit[0][0]} targets this session's host "
                            f"process ({hit[0][1]})")
                continue
            if not args:
                continue
            if not anc:
                # No ancestry available — conservative: block kill patterns
                # naming a known host stack.
                for a in args:
                    if _HOST_STACK_RE.search(a):
                        return (f"{tool} pattern '{a}' names the stack "
                                "hosting this session")
                continue
            for pattern in args:
                try:
                    rx = re.compile(pattern)
                except re.error:
                    rx = None
                for _pid, name, cmdline in anc:
                    if tool == "killall":
                        matched = pattern == name
                    elif "-f" in flags:
                        matched = bool(rx.search(cmdline) if rx
                                       else pattern in cmdline)
                    else:
                        matched = bool(rx.search(name) if rx
                                       else pattern in name)
                    if matched:
                        excerpt = (cmdline or name)[:90]
                        return (f"{tool} pattern '{pattern}' matches this "
                                f"session's host process: {excerpt}")
    except Exception:
        return ""
    return ""


_DEFAULT_BASH_DENY_PATTERNS: tuple[str, ...] = (
    r"\brm\s+(-[a-zA-Z]*[rR][a-zA-Z]*[fF]|-[a-zA-Z]*[fF][a-zA-Z]*[rR])\b",
    # The same delete, spelled with the flags apart. The pattern above
    # needs r and f in ONE token, so `rm -r -f build`, `rm -f -r build`
    # and `rm --recursive --force build` all matched nothing — and split
    # flags are the spelling a model produces when it is being careful.
    # Two lookaheads, the idiom already proven on `git clean` and `find`,
    # so a later `;` or `|` cannot smuggle the second half in from
    # another command.
    r"\brm\b"
    r"(?=[^;|&]*\s-(?:[a-zA-Z]*f\b|-force\b))"
    r"(?=[^;|&]*\s-(?:[a-zA-Z]*r\b|-recursive\b))",
    r"\brm\s+-[a-zA-Z]*\s+/(?:\s|$)",
    r"\bdd\s+if=",
    r"\bdd\s+of=/dev/",
    r"\bmkfs(\.|\s)",
    # Cancelling by USER, not by job: scancel -u / --user ends every job
    # that person has queued or running, including the ones this session
    # knows nothing about and the ones somebody else is waiting on. On a
    # shared cluster the blast radius is hours of other people's compute,
    # and there is no version of "the agent meant well" that gives it back.
    # A single named job stays reachable and goes through the normal gate.
    r"\bscancel\b[^;|&]*(?:-u\b|--user\b)",
    r"\bscontrol\b[^;|&]*\bsuspend\b",
    # The same shape one layer down: killall -u ends every process a user
    # owns, which on a login node is their editor, their shell and their
    # running calculations.
    r"\bkillall\b[^;|&]*-u\b",
    r"\bpkill\b[^;|&]*(?:-u\b|--uid\b|-U\b)",
    # Ending the machine, as a COMMAND. Matched anywhere in the line, this
    # refused `grep -rn "shutdown\\|def stop" engine.py` and, worse, a
    # `git commit -m "... on shutdown"` -- it read the commit message and
    # cost a session its commit (driven 2026-09-17). So the word must stand
    # where a command stands: line start or after a separator, optionally
    # quoted (python -c "os.system('reboot')") or path-qualified.
    r"""(?:^|[;|&`(])[\s'\"]*(?:sudo\s+)?(?:/\S*/)?"""
    r"(?:shutdown|reboot|halt|poweroff|init\s+[06])\b",
    r"\bsudo\b",
    r"(?:^|\s)su\s+-",
    r"git\s+push\s+(?:[^|;&]*\s)?(?:--force(?!-with-lease)|-f\b)",
    r"git\s+reset\s+--hard\b",
    r"git\s+branch\s+-D\b",
    r"git\s+branch\s+-d\b",                # local branch delete (gentle form)
    r"git\s+branch\s+--delete\b",
    r"git\s+push\s+[^|;&]*--delete\b",     # remote branch delete
    r"git\s+push\s+\S+\s+:\S",             # legacy 'git push origin :branch' delete
    r"git\s+tag\s+-d\b",                   # tag delete
    r"git\s+tag\s+--delete\b",
    r"git\s+worktree\s+remove\b",
    # The stash stack belongs to the REPOSITORY, not to a worktree. Four
    # sessions working in worktrees of one repository share it, so a pop
    # takes whatever is on top — which may be another session's work,
    # applied into the wrong tree with nothing to say it happened. One
    # session reached for it on 2026-09-18 with three others running.
    #
    # Anchored on the SUBCOMMAND, past git's own options: matching the
    # word anywhere would refuse `git commit -m "drop the stash usage"`,
    # which is how the shutdown pattern once cost a session its commit.
    # `list` and `show` are reads and stay available.
    r"""(?:^|[;|&`(])[\s'\"]*(?:sudo\s+)?git\s+"""
    r"(?:(?:--no-pager|--paginate|-C\s+\S+|-c\s+\S+)\s+)*"
    r"stash\b(?!\s+(?:list|show)\b)",
    # `-fd` was the only spelling this caught. `git clean -f -d` and
    # `git clean -xdf` — the forms people actually type, and the more
    # destructive ones — matched nothing and fell through to the confirm
    # gate, which under an unattended profile means they ran. Match the
    # FLAGS instead of one spelling of them: force, plus either recursing
    # into directories or including ignored files, in any order and
    # across any number of tokens.
    r"git\s+clean\b"
    r"(?=[^;|&]*(?:\s-[a-zA-Z]*f[a-zA-Z]*\b|\s--force\b))"
    r"(?=[^;|&]*\s-[a-zA-Z]*[dx][a-zA-Z]*\b)",
    # Committing under someone else's name, or with a forged date. The
    # auto-allow entry for `git commit -m` anchors on the message flag
    # and ignores the rest of the line, so this ran unattended.
    r"git\s+commit\b[^;|&]*--author[=\s]",
    r"git\s+commit\b[^;|&]*--date[=\s]",
    r"git\s+update-ref\s+-d\b",
    r"git\s+filter-(?:branch|repo)\b",     # history rewriting
    r">\s*/dev/(sd|nvme|hd|xvd)",
    r">\s*/etc/",
    r"\bchmod\s+-?R?\s*777\b",
    # `chmod 0777` and `chmod a+rwx` are the same act and neither matched.
    # Worse than undenied: chmod is on the AUTO-ALLOW list, whose comment
    # says "any chmod except 777 (deny-list)" — so `chmod 0777 /etc/passwd`
    # ran with no prompt at all. Deny is checked before auto-allow, so
    # covering the spellings here is what makes that comment true.
    r"\bchmod\b[^;|&]*\s0?777\b",
    r"\bchmod\b[^;|&]*\s[ugoa]*\+rwx\b",
    r":\s*\(\s*\)\s*\{",  # fork bomb
    r"\bcurl\b[^|;]*\|\s*(?:sh|bash|zsh)",
    r"\bwget\b[^|;]*\|\s*(?:sh|bash|zsh)",
    # Fetch-and-run with anything in between. The two above require the
    # shell to be the IMMEDIATE next stage, so `curl u | tee /tmp/x | sh`
    # defeated them, and so did piping into an interpreter rather than a
    # shell. It is the install idiom, the payload is remote code the rest
    # of the stack never sees, and an arbitrary project folder is exactly
    # where a model reaches for it.
    r"\b(?:curl|wget)\b[^;&]*\|(?:[^;&]*\|)*"
    r"\s*(?:sh|bash|zsh|python3?|perl|ruby|node)\b",
    r"--break-system-packages\b",
    r"\bnpm\s+publish\b",
    r"\bpip\s+install\b[^|;]*--target\s+/(?:usr|etc|bin|lib|var)",
    r"\bcrontab\s+-r\b",
    # `rm -rf ~` is denied above; `find ~ -delete` was not, and it empties
    # the same directory. Measured through the whole gate: under
    # bypassPermissions every one of `find ~ -delete`, `find / -delete`,
    # `find $HOME -delete` and `find ~ -type f -exec rm {} \;` came back
    # ALLOWED, while the rm spelling of the same act was refused. The rule
    # existed as a sentence and the mechanism permitted its opposite.
    #
    # Same repair as the `git clean` entry above: match what the command
    # DOES, not one spelling of it. Two conditions, either order, any
    # number of tokens between them — a destructive action, and a search
    # root that is absolute or home-anchored. A relative root is left to
    # the ordinary gate on purpose: `find . -name '*.pyc' -delete` inside a
    # workspace is honest cleanup, and blanket-denying it would push the
    # model towards spellings nobody has thought about.
    r"\bfind\b"
    r"(?=[^;|&]*\s(?:~|\$\{?HOME\}?|/))"
    r"(?=[^;|&]*\s-(?:delete\b|(?:exec|execdir|ok|okdir)\s+"
    r"(?:rm|rmdir|unlink|shred|truncate|dd)\b))",
    # Reading the OS credential store, where DELFIN keeps API keys when
    # agent.credentials.store selects it. The keyring is read by the DELFIN
    # process only; a command that prints an entry hands the key to the
    # transcript. Command position for the CLIs (a grep for the word
    # stays free), anywhere for the Python call and the D-Bus service name.
    # Not a boundary on its own: the sandbox unsets DBUS_SESSION_BUS_ADDRESS
    # and the socket guard refuses the bus socket; an obfuscated python -c
    # is caught there, not here.
    r"""(?:^|[;|&`(])[\s'\"]*(?:sudo\s+)?(?:/\S*/)?"""
    r"(?:secret-tool\s+(?:lookup|search)|"
    r"security\s+(?:find-(?:generic|internet)-password|dump-keychain)|"
    r"keyring\s+get)\b",
    r"\bpython[\w.]*\s+(?:-\S+\s+)*-m\s+keyring\b",
    r"\bkeyring\s*\.\s*get_(?:password|credential)\b",
    r"\borg\.freedesktop\.secrets\b",
    r"\bGet-StoredCredential\b",
)

# DELFIN's own programs: the read-only subcommands, one end-anchored
# pattern each. Input: a shell segment. A pattern matches only the program,
# the subcommand words, and then options from that subcommand's own list
# and positionals that cannot be read as an option (a bare or quoted word
# not starting with "-"), so neither an abbreviated acting flag
# (argparse takes `--rep` for `--repair`) nor a sub-subcommand (`bench`
# plus the word `run`) nor a redirect, substitution or chain rides on it.
# A subcommand that acts -- stops or pauses processes, writes or deletes
# credentials, moves or writes report files, writes outside the
# workspace, changes a schedule or a baseline, answers an approval,
# starts a model session, a calculation or a SLURM job -- has no entry and
# goes to the dialog (asked when someone can ask, refused headless).
#
# Classification, from the argparse parsers (delfin/agent/cli.py
# build_parser; delfin/cli.py main):
#   delfin-agent, read-only: -h/--help anywhere, --version, bench
#     list|latest|audit|compare|gate, session ls|search, messages
#     ls|status, memory [tidy] without --apply, approvals [ls]|show|watch,
#     skills [proposals]|show, bug [ls], scheduler [status], stop-all
#     --check, doctor without --repair, capabilities, gate explain, report,
#     watch, where [--ssh-config] without --write/--attach, sessions, jobs,
#     jobs watch --status.
#   delfin-agent, acting: the bare program and any unknown first word
#     (routed to chat), chat, run, init, bench [run]|set-baseline|rebase|
#     nightly, credentials *, session export, watchpost * (run and diff
#     write a report under ~/.delfin), memory tidy --apply, approvals
#     approve|deny|answer, skills accept|reject, bug triage (writes
#     triage.md and a patch)|solve|watch, scheduler start|stop|add-bench,
#     stop-all, pause, resume, doctor --repair, where --attach|--write,
#     jobs watch --on|--off, test-on-slurm.
#   delfin, read-only: -h/--help, -V/--version, doctor [--json],
#     qm_check, csp_check, mlp_check, analysis_check.
#   delfin, acting: the bare program (a workflow run), every flag form
#     (--define, --recalc, --cleanup, --purge, --json ...), cleanup, stop,
#     co2, run_orca, qm_run, tadf_xtb, hyperpol, cluster, review; and every
#     other delfin-* program (pipeline, step, build, guppy, manta, fukui,
#     voila, app, the servers, the indexer).
# Rejected: one prefix pattern with a deny-list of acting subcommands (an
# open list: a new subcommand would be free on arrival); reading the
# parser at import time (the classification is a decision, not a fact the
# parser holds). Cost: about 40 regex searches more per segment that
# reaches the DELFIN entries, all anchored at the program name.
_CLI_WORD = r"[A-Za-z0-9_./~@:+=,%][A-Za-z0-9_./~@:+=,%-]*"
_CLI_ARG = (r"(?:" + _CLI_WORD + r"|'[^'\-][^']*'"
            r"|\"[^\"$`\\!\-][^\"$`\\!]*\")")
_CLI_TAIL = r"(?:\s+2>(?:&1|/dev/null))?\s*$"
_PY_M = r"python(?:3(?:\.\d+)?)?\s+-m\s+"


def _cli_read_only(prog: str, words: str, *, flags: tuple = (),
                   valued: tuple = (), positional: bool = False) -> str:
    alts = [re.escape(f) for f in flags]
    alts += [re.escape(v) + r"(?:=|\s+)" + _CLI_ARG for v in valued]
    if positional:
        alts.append(_CLI_ARG)
    body = r"^\s*" + prog + (r"\s+" + words if words else "")
    if alts:
        body += r"(?:\s+(?:" + "|".join(alts) + r"))*"
    return body + _CLI_TAIL


